        }
        self.claimed[here.zid] = True;
        self.affected.add(here.zid);
        visit [->:ParentZone:->];
    }
}

walker CountAscent {
    """Linear ascent over ParentZone recomputing each ancestor's subtree
    override count. Dead ends at the region root disengage."""
    has counter: ConfigTree;

    can step with Zone entry {
        self.counter.counts[here.zid] = self.counter.subtree_overrides(
            here.zid
        );
        visit [here <-:ParentZone:<-] else { disengage; }
    }
}

walker WriteTally {
    """Descends ParentZone edges tallying live override records.
    Skip-guard keeps shared zones once-only."""
    has count: int = 0;
    has claimed: dict[str, bool] = {};

    can step with Zone entry {
        if here.zid in self.claimed {
            skip;
        }
        self.claimed[here.zid] = True;
        mine: list[Write] = [here ->:Applies:->];
        for wr in mine {
            if not wr.retired {
                self.count += 1;
            }
        }
        visit [->:ParentZone:->];
    }
}

walker ZoneAscent {
    """Linear climb over ParentZone including the entry zone."""
    has order: list[str] = [];

    can step with Zone entry {
        self.order.append(here.zid);
        visit [here <-:ParentZone:<-] else { disengage; }
    }
}

walker EffectiveProbe {
    """Nearest-wins search along the parent chain; stops at the first
    live value for the key."""
    has tree: ConfigTree;
    has key: str;
    has value: int | None = None;

    can step with Zone entry {
        v = self.tree._live_value(here, self.key);
        if v is not None {
            self.value = v;
            disengage;
        }
        visit [here <-:ParentZone:<-] else { disengage; }
    }
}

obj ConfigTree {
    """Compatibility facade. Zone ids and config keys are public API
    currency; lookup maps are domain state."""
    has by_zid: dict[str, Zone] = {};
    has by_key: dict[str, ConfigKey] = {};
    has counts: dict[str, int] = {};

    def add_zone(zid: str, parent: str | None = None) -> str {
        if zid in self.by_zid {
            raise ValueError("duplicate zone " + zid);
        }
        z := Zone(zid=zid);
        if parent is not None {
            p = self.by_zid[parent];
            p +>:ParentZone:+> z;
        }
        self.by_zid[zid] = z;
        return zid;
    }

    """Two-phase write: sweep the affected subtree, then drop caches,
    update or create the Write record, and recount up the chain."""
    def set_override(zid: str, key: str, value: int) -> None {
        z = self.by_zid[zid];
        k = self._intern(key);
        w = z spawn InvalidationSweep();
        mine: list[Write] = [z ->:Applies:->];
        hit: Write | None = None;
        for wr in mine {
            if not wr.retired and wr.key_name == key {
                hit = wr;
            }
        }
        if hit is None {
            wr := Write(key_name=key, value=value);
            z +>:Applies:+> wr;
            wr +>:ForKey:+> k;
        } else {
            hit.value = value;
        }
        self._invalidate(w);
        z spawn CountAscent(counter=self);
    }

    def clear_override(zid: str, key: str) -> bool {
        z = self.by_zid[zid];
        k = self.by_key.get(key);
        if k is None {
            return False;
        }
        mine: list[Write] = [z ->:Applies:->];
        hit: Write | None = None;
        for wr in mine {
            if not wr.retired and wr.key_name == key {
                hit = wr;
            }
        }
        if hit is None {
            return False;
        }
        w = z spawn InvalidationSweep();
        # retire the record and sever its links
        hit.retired = True;
        z del ->:Applies:-> hit;
        keys: list[ConfigKey] = [hit ->:ForKey:->];
        for kk in keys {
            hit del ->:ForKey:-> kk;
        }
        self._invalidate(w);
        z spawn CountAscent(counter=self);
        return True;
    }

    """Nearest override wins; the ascent order is the documented
    evaluation order and is pinned by tests."""
    def effective(zid: str, key: str) -> int | None {
        # nearest override wins; spawn the probe from zid itself
        w = self.by_zid[zid] spawn EffectiveProbe(tree=self, key=key);
        return w.value;
    }

    def _intern(name: str) -> ConfigKey {
        k = self.by_key.get(name);
        if k is None {
            k = ConfigKey(name=name);
            self.by_key[name] = k;
        }
        return k;
    }

    def _invalidate(w: InvalidationSweep) -> None {
        for t in w.affected {
            tz = self.by_zid[t];
            tz.cache = {};
            tz.materialized = False;
        }
    }

    def _live_value(z: Zone, key: str) -> int | None {
        mine: list[Write] = [z ->:Applies:->];
        for wr in mine {
            if not wr.retired and wr.key_name == key {
                return wr.value;
            }
        }
        return None;
    }

    def chain(zid: str) -> list[str] {
        w = self.by_zid[zid] spawn ZoneAscent();
        return w.order;
    }

    """Walker-based: counts live write records across the subtree."""
    def subtree_overrides(zid: str) -> int {
        w: WriteTally = self.by_zid[zid] spawn WriteTally();
        return w.count;
    }

    def materialize_view(zid: str) -> dict[str, int | None] {
        truth = self.recompute_view(zid);
        z = self.by_zid[zid];
        fresh: dict[str, int] = {};
        for kn in truth.keys() {
            v = truth[kn];
            if v is not None {
                fresh[kn] = v as int;
            }
        }
        z.cache = fresh;
        z.materialized = True;
        return truth;
    }

    def recompute_view(zid: str) -> dict[str, int | None] {
        truth: dict[str, int | None] = {};
        ids = reversed(self.chain(zid));
        for t in ids {
            tz = self.by_zid[t];
            mine: list[Write] = [tz ->:Applies:->];
            for wr in mine {
                if not wr.retired {
                    truth[wr.key_name] = wr.value;
                }
            }
        }
        return truth;
    }

    def effective_view(zid: str) -> dict[str, int | None] {
        return self.materialize_view(zid);
    }

    def override_count(zid: str) -> int {
        return self.counts.get(zid, 0);
    }

    """Invariant probe: materialized views must match recomputation."""
    def coherent() -> bool {
        for zid in self.by_zid.keys() {
            z = self.by_zid[zid];
            if not z.materialized {
                continue;
            }
            truth = self.recompute_view(zid);
            same: bool = True;
            if len(z.cache.keys()) != len(truth.keys()) {
                same = False;
            }
            for kn in truth.keys() {
                if z.cache.get(kn, None) != truth[kn] {
                    same = False;
                }
            }
            if not same {
                return False;
            }
        }
        return True;
    }
}

floor_jac:
"""Distributed configuration propagation tree.

Zones form a region -> cluster -> node hierarchy. Configuration overrides
are attached at any zone; the effective value of a key at a zone is defined
by the NEAREST zone on its ancestor chain that overrides it. Every zone
caches a materialized effective view; writes must invalidate caches down
the subtree and maintain override counts up the chain.

Hand-rolled machinery:
- parent/children pointers over the zone tree with recursive ascent and
  queue-based subtree invalidation sweeps (C1)
- per-key override adjacency dicts plus BFS frontier walks (C2)
- two-phase cache invalidation cascade with coherence invariants (C5)
"""
class Zone {
    def init(self: Zone, zid: Any, parent: Any = None) -> object {
        self.zid = zid;
        self.parent = parent;
        self.children = [];
        self.overrides = {};
        self.cache = {};
        self.materialized = False;
    }
}
class ConfigTree {
    def init(self: ConfigTree) -> object {
        self.zones = {};
        self.counts = {};
    }
    def add_zone(self: ConfigTree, zid: Any, parent: Any = None) -> object {
        if (zid in self.zones) {
            raise ValueError("duplicate zone");
        }
        if ((parent is not None) and (parent not in self.zones)) {
            raise KeyError(parent);
        }
        p = self.zones[parent] if (parent is not None) else None;
        z = Zone(zid, p);
        if (p is not None) {
            p.children.append(z);
        }
        self.zones[zid] = z;
        return zid;
    }
    def _subtree_ids(self: ConfigTree, zid: Any) -> list {
        out: list = [];
        q: list = [zid];
        while len(q) > 0 {
            cur: str = q.pop(0) as str;
            out.append(cur);
            kids: list = (self.zones[cur] as Zone).children as list;
            for c in kids {
                cz = c as Zone;
                q.append(cz.zid);
            }
        }
        return out;
    }
    def _recount_up(self: ConfigTree, zid: Any) -> object {
        cur2: Zone | None = self.zones[zid] as Zone | None;
        while (cur2 is not None) {
            cz: str = cur2.zid as str;
            total: int = 0;
            for t in self._subtree_ids(cz) {
                zz = self.zones[t] as Zone;
                total += len(zz.overrides as dict);
            }
            self.counts[cz] = total;
            nxt: Zone | None = cur2.parent as Zone | None;
            cur2 = nxt;
        }
    }
    """Write an override; invalidate subtree caches; recount up."""
    def set_override(self: ConfigTree, zid: Any, key: Any, value: Any) -> object {
        z = self.zones[zid];
        z.overrides[key] = value;
        for t in self._subtree_ids(zid) {
            zt = self.zones[t];
            zt.cache.clear();
            zt.materialized = False;
        }
        self._recount_up(zid);
    }
    """Remove an override if present; same invalidation protocol.
        Returns True when an override was removed."""
    def clear_override(self: ConfigTree, zid: Any, key: Any) -> object {
        z = self.zones[zid];
        if (key not in z.overrides) {
            return False;
        }
        delete(z.overrides[key],);
        for t in self._subtree_ids(zid) {
            zt = self.zones[t];
            zt.cache.clear();
            zt.materialized = False;
        }
        self._recount_up(zid);
        return True;
    }

    """Nearest override wins: walk the chain from zid upward."""
    def effective(self: ConfigTree, zid: Any, key: Any) -> object {
        cur3: Zone | None = self.zones[zid] as Zone | None;
        while (cur3 is not None) {
            ov = cur3.overrides as dict;
            if (key in ov) {
                return ov[key];
            }
            up3: Zone | None = cur3.parent as Zone | None;
            cur3 = up3;
        }
        return None;
    }
    """Materialized view of all keys visible at zid (cached)."""
    def effective_view(self: ConfigTree, zid: Any) -> dict {
        z = self.zones[zid] as Zone;
        if (not z.materialized) {
            merged: dict = {};
            ids: list = self.chain(zid) as list;
            for rid in reversed(ids) {
                zz = self.zones[rid] as Zone;
                ov = zz.overrides as dict;
                for ok in ov.keys() {
                    merged[ok] = ov[ok];
                }
            }
            z.cache = merged;
        }
        z.materialized = True;
        return z.cache as dict;
    }
    """Observable evaluation order: nearest zone first."""
    def chain(self: ConfigTree, zid: Any) -> list {
        chain = [];
        cur = self.zones[zid];
        while (cur is not None) {
            chain.append(cur.zid);
            cur = cur.parent;
        }
        return chain;
    }
    def override_count(self: ConfigTree, zid: Any) -> object {
        return self.counts.get(zid, 0);
    }
    """Invariant: every materialized cached view equals recomputed
        truth; unmaterialized caches are trivially coherent."""
    def coherent(self: ConfigTree) -> object {
        for zid in self.zones.keys() {
            z = self.zones[zid] as Zone;
            if (not z.materialized) {
                continue;
            }
            truth = self.effective_view(zid);
            if (z.cache != truth) {
                return False;
            }
        }
        return True;
    }
}

