"""Dependency-tree renderer with shared-node visibility.

A verification project's modules form a "needs" graph rendered as a tree
from a root module. The original renderer closed over ONE visited set
shared across the whole traversal, so a module reachable from two branches
was attached under only the first branch -- ``veriq tree`` and its
``--invert`` impact view under-reported shared dependency paths. The fix
tracks visited state per root-to-node path (copied down each branch), so
a shared node appears under every parent while repetition along a single
path is still prevented.
Ref: ut-issl/veriq#260
"""


def load_tree(names, depends_on):
    """``depends_on``: ``(user, dependency)`` pairs -- user needs dependency."""
    dep = {n: [] for n in names}
    rdep = {n: [] for n in names}
    for user, used in depends_on:
        dep[user].append(used)
        rdep[used].append(user)
    return {"names": list(names), "dep": dep, "rdep": rdep}


def render_edges(tree, root):
    """Sorted ``parent>child`` render pairs below ``root``.

    Per-path visited policy: a child is skipped only when it already sits
    on the current root-to-node path, never because another branch got
    there first.
    """
    out = []

    def walk(name, path):
        for child in tree["dep"].get(name, []):
            if child in path:
                continue
            out.append("%s>%s" % (name, child))
            walk(child, path | {child})

    walk(root, {root})
    return sorted(out)


def dependencies_of(tree, node):
    """Transitive closure of what ``node`` needs (inclusive), sorted."""
    seen = {node}
    stack = [node]
    while stack:
        cur = stack.pop()
        for nxt in tree["dep"].get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return sorted(seen)


def dependents_of(tree, node):
    """Transitive closure of who needs ``node`` (inclusive), sorted."""
    seen = {node}
    stack = [node]
    while stack:
        cur = stack.pop()
        for nxt in tree["rdep"].get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return sorted(seen)

candidate_osp_jac:
"""Dependency-tree renderer with shared-node visibility, lifted to OSP.

The recursive per-path walk becomes a fan of BranchRender walkers: every
branch spawns its own walker carrying a COPY of the root-to-node path, so
a module reachable from two branches renders under both (the issue's fix)
while repeats along one path are denied. Closure queries become flooding
walkers over typed Needs / UsedBy edges with claim-map cycle policy --
jac 0.36.1 walkers do not dedupe, so revisits are `skip`ed explicitly.
Ref: ut-issl/veriq#260
"""
node Module {
    has name: str;
}
edge Needs {}    # user -> dependency
edge UsedBy {}   # dependency -> user

obj RenderSink {
    has rendered: list[str];
}

"""Loader handle: id-string parameters resolve through this lookup map."""
obj Tree {
    has modules: dict[str, Module];
    has names: list[str];

    def resolve(name: str) -> Module | None {
        return self.modules.get(name);
    }
}

"""Deterministic fresh-graph builder; creation order = fixture order."""
def load_tree(names: list[str], depends_on: list[tuple[str, str]]) -> Tree {
    tree = Tree(modules={}, names=[]);
    for n in names {
        m = Module(name=n);
        root ++> m;
        tree.modules[n] = m;
        tree.names.append(n);
    }
    for (user, used) in depends_on {
        u = tree.modules[user];
        d = tree.modules[used];
        u +>:Needs:+> d;
        d +>:UsedBy:+> u;
    }
    return tree;
}

walker BranchRender {
    has path: dict[str, bool] = {};
    has parent_name: str = "";
    has sink: RenderSink | None = None;

    can step with Module entry {
        # Per-path policy: deny only if already on THIS root-to-node path.
        if here.name in self.path {
            skip;
        }
        path = dict(self.path);
        path[here.name] = True;
        if self.parent_name != "" and self.sink is not None {
            self.sink.rendered.append(self.parent_name + ">" + here.name);
        }
        # Each branch gets a fresh walker with a copied path.
        for k in [here->:Needs:->] {
            k spawn BranchRender(path=path, parent_name=here.name, sink=self.sink);
        }
    }
}

# (`root` is a jac keyword, hence root_name)
def render_edges(tree: Tree, root_name: str) -> list[str] {
    start = tree.resolve(root_name);
    if start is None {
        return [];
    }
    sink = RenderSink(rendered=[]);
    start spawn BranchRender(path={}, parent_name="", sink=sink);
    return sorted(sink.rendered);
}

walker DepFlood {
    has claimed: dict[str, bool] = {};
    has members: list[str] = [];

    can step with Module entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.members.append(here.name);
        visit [->:Needs:->];
    }
}

walker UsedByFlood {
    has claimed: dict[str, bool] = {};
    has members: list[str] = [];

    can step with Module entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.members.append(here.name);
        visit [->:UsedBy:->];
    }
}

# (`node` is a jac keyword, hence name)
def dependencies_of(tree: Tree, name: str) -> list[str] {
    start = tree.resolve(name);
    if start is None {
        return [name];
    }
    w = start spawn DepFlood(claimed={});
    return sorted(w.members);
}

# (`node` is a jac keyword, hence name)
def dependents_of(tree: Tree, name: str) -> list[str] {
    start = tree.resolve(name);
    if start is None {
        return [name];
    }
    w = start spawn UsedByFlood(claimed={});
    return sorted(w.members);
}

