"""Schema profile hierarchy resolution.

Before-code synthesized from opsmill/infrahub#8968: root resolution
walked ``parent`` pointers with no cycle guard, so a kind whose parent
was itself sent the resolver into infinite recursion. The hand-rolled
ascent here carries an explicit visited-kind set: a self-parent or any
revisited ancestor raises ``SchemaCycleError`` instead of recursing
forever, and lineage queries share the same guard.
"""


class SchemaCycleError(ValueError):
    """The profile hierarchy loops back on itself."""


class SchemaHierarchy:
    def __init__(self):
        self.parent_of = {}   # kind -> parent kind | None

    def register_kind(self, kind, parent_kind=None):
        if parent_kind is not None and parent_kind not in self.parent_of:
            raise KeyError("unknown parent kind")
        # NOTE: a self-parent is accepted at registration time -- exactly
        # the corrupt shape issue #8968 observed on sync/arista.
        self.parent_of[kind] = parent_kind

    def _ascend(self, kind):
        """Walk parents from ``kind``; returns (chain, hit_cycle)."""
        chain = []
        seen = set()
        cur = kind
        while cur is not None:
            if cur in seen:
                return chain, True
            seen.add(cur)
            chain.append(cur)
            cur = self.parent_of.get(cur)
        return chain, False

    def resolve_root(self, kind):
        """The most distant ancestor kind name."""
        chain, hit_cycle = self._ascend(kind)
        if hit_cycle:
            raise SchemaCycleError("hierarchy cycle at %r" % chain[-1])
        return chain[-1]

    def lineage(self, kind):
        """Ancestor kinds nearest-first; raises on cycle."""
        chain, hit_cycle = self._ascend(kind)
        if hit_cycle:
            raise SchemaCycleError("hierarchy cycle at %r" % chain[-1])
        return chain[1:]

    def children_of(self, kind):
        """Sorted direct child kinds of ``kind``."""
        return sorted(k for k, p in self.parent_of.items() if p == kind)

candidate_osp_jac:
"""Schema profile hierarchy resolution, lifted to OSP.

Kinds are ``Kind`` nodes; ``parent`` pointers become typed ``Extends``
edges. Root resolution and lineage climb the typed edges with one
walker whose seen-set is the explicit cycle policy: the self-parenting
corruption from issue #8968 raises ``SchemaCycleError`` instead of
recursing forever.
"""

class SchemaCycleError(ValueError) {}

node Kind {
    has name: str;
}

edge Extends: Kind --> Kind {}

node SchemaRoot {}

"""Fresh hierarchy root."""
def new_hierarchy() -> SchemaRoot {
    root ++> (r := SchemaRoot());
    return r;
}

def _find_kind(h: SchemaRoot, kind: str) -> Kind | None {
    hits = [k for k in [h -->][?:Kind] if k.name == kind];
    if len(hits) == 0 {
        return None;
    }
    return hits[0];
}

"""Register a kind; a self-parent is accepted, as in the source."""
def register_kind(h: SchemaRoot, kind: str, parent_kind: str | None = None) -> None {
    if _find_kind(h, kind) is not None {
        raise ValueError("duplicate kind");
    }
    root ++> (k := Kind(name=kind));
    h ++> k;
    if parent_kind is not None {
        p = _find_kind(h, parent_kind);
        if p is None {
            raise KeyError("unknown parent kind");
        }
        k +>:Extends:+> p;
    }
}

walker RootClimb {
    """Climbs Extends edges; flags a revisit instead of looping."""
    has claimed: dict[str, bool] = {};
    has chain: list[str] = [];
    has hit_cycle: bool = False;

    can step with Kind entry {
        if here.name in self.claimed {
            self.hit_cycle = True;
            skip;
        }
        self.claimed[here.name] = True;
        self.chain.append(here.name);
        visit [->:Extends:->];
    }
}

def _climb(h: SchemaRoot, kind: str) -> list[str] {
    k = _find_kind(h, kind);
    if k is None {
        raise KeyError("unknown kind");
    }
    w = k spawn RootClimb();
    if w.hit_cycle {
        raise SchemaCycleError("hierarchy cycle");
    }
    return w.chain;
}

"""The most distant ancestor kind name."""
def resolve_root(h: SchemaRoot, kind: str) -> str {
    chain = _climb(h, kind);
    return chain[-1];
}

"""Ancestor kinds nearest-first; raises on cycle."""
def lineage(h: SchemaRoot, kind: str) -> list[str] {
    chain = _climb(h, kind);
    return chain[1:];
}

"""Sorted direct child kinds of `kind`."""
def children_of(h: SchemaRoot, kind: str) -> list[str] {
    k = _find_kind(h, kind);
    if k is None {
        raise KeyError("unknown kind");
    }
    return sorted(c.name for c in [k <-:Extends:<-]);
}

