"""Probabilistic-composer column DAG ancestry queries.

probcomp/bdbcontrib#73: the composer registers generators (columns) into a
DAG of parent links and answers ad-hoc queries by walking that DAG with an
adjacency list and recursive descent -- column_dependence_probability alone is
"a simple graph walk in the DAG". The lifted surface keeps the walk results as
sets: ancestry closures, dependence reachability, and the Markov blanket of a
column (its parents, children, and co-parents).
"""


class Composer:
    """In-memory registry of generator columns and their parent links."""

    def __init__(self):
        self.columns = {}   # name -> list of parent names

    def create_generator(self, name, parents=()):
        """Register ``name`` depending on ``parents``; unknown parents fail."""
        for p in parents:
            if p not in self.columns:
                raise KeyError(p)
        self.columns[name] = list(parents)

    def _walk(self, start, links):
        seen = set()
        stack = list(links(start))
        while stack:
            cur = stack.pop()
            if cur in seen or cur == start:
                continue
            seen.add(cur)
            stack.extend(links(cur))
        return seen

    def _parents(self, name):
        return self.columns.get(name, [])

    def _children(self, name):
        return sorted(c for c, ps in self.columns.items() if name in ps)

    def ancestors(self, name):
        """All transitive parents of ``name`` (sorted set)."""
        if name not in self.columns:
            return []
        return sorted(self._walk(name, self._parents))

    def descendants(self, name):
        """All transitive children of ``name`` (sorted set)."""
        if name not in self.columns:
            return []
        return sorted(self._walk(name, self._children))

    def depends_on(self, ancestor, descendant):
        """True when ``descendant`` transitively depends on ``ancestor``."""
        if descendant not in self.columns:
            return False
        return ancestor in self._walk(descendant, self._parents)

    def markov_blanket(self, name):
        """Parents + children + co-parents of ``name`` (sorted set).

        Unknown columns yield an empty blanket.
        """
        if name not in self.columns:
            return []
        blanket = set(self._parents(name)) | set(self._children(name))
        for child in self._children(name):
            blanket.update(self._parents(child))
        blanket.discard(name)
        return sorted(blanket)

candidate_osp_jac:
"""Probabilistic-composer column DAG ancestry queries.

probcomp/bdbcontrib#73 lifted to OSP: generator columns become Column
archetypes and parent links become typed DependsOn edges with a mirrored
DependentOf edge so child queries stay walker-native. The recursive descent
over the adjacency list becomes flooding walkers whose seen map is the cycle
policy, and the Markov blanket is assembled from per-node one-hop probes --
all results are plain sets of column names.
"""
node Column {
    has name: str;
}
edge DependsOn {}
edge DependentOf {}

"""Composer handle: column names resolve through this lookup map."""
obj Composer {
    has cols: dict[str, Column];

    def resolve(name: str) -> Column | None {
        return self.cols.get(name);
    }
}

walker ParentHop {
    has outs: list[str] = [];
    has started: bool = False;

    can step with Column entry {
        if not self.started {
            self.started = True;
            visit [->:DependsOn:->];
        } else {
            if here.name not in self.outs {
                self.outs.append(here.name);
            }
        }
    }
}

walker ChildHop {
    has outs: list[str] = [];
    has started: bool = False;

    can step with Column entry {
        if not self.started {
            self.started = True;
            visit [->:DependentOf:->];
        } else {
            if here.name not in self.outs {
                self.outs.append(here.name);
            }
        }
    }
}

walker AncestorFlood {
    has claimed: dict[str, bool] = {};
    has reached: list[str] = [];
    has start_name: str = "";

    can step with Column entry {
        if here.name in self.claimed {
            skip;
        }
        if here.name != self.start_name {
            self.reached.append(here.name);
        }
        self.claimed[here.name] = True;
        visit [->:DependsOn:->];
    }
}

walker DescendantFlood {
    has claimed: dict[str, bool] = {};
    has reached: list[str] = [];
    has start_name: str = "";

    can step with Column entry {
        if here.name in self.claimed {
            skip;
        }
        if here.name != self.start_name {
            self.reached.append(here.name);
        }
        self.claimed[here.name] = True;
        visit [->:DependentOf:->];
    }
}

walker DependenceProbe {
    has target: str = "";
    has found: bool = False;
    has claimed: dict[str, bool] = {};
    has started: bool = False;

    can step with Column entry {
        if not self.started {
            self.started = True;
            self.claimed[here.name] = True;
            visit [->:DependsOn:->];
        } else {
            if here.name == self.target {
                self.found = True;
                disengage;
            }
            if here.name in self.claimed {
                skip;
            }
            self.claimed[here.name] = True;
            visit [->:DependsOn:->];
        }
    }
}

def _parents_of(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn ParentHop();
    return w.outs;
}

def _children_of(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn ChildHop();
    return w.outs;
}

def create_generator(g: Composer, name: str, parents: list[str] = []) -> None {
    for p in parents {
        if g.resolve(p) is None {
            raise KeyError(p);
        }
    }
    c = Column(name=name);
    root ++> c;
    g.cols[name] = c;
    for p in parents {
        pc = g.resolve(p);
        if pc is None {
            continue;
        }
        c +>:DependsOn:+> pc;
        pc +>:DependentOf:+> c;
    }
}

"""All transitive parents of ``name`` (sorted set); unknown yields []."""
def ancestors(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn AncestorFlood(start_name=name);
    return sorted(w.reached);
}

"""All transitive children of ``name`` (sorted set); unknown yields []."""
def descendants(g: Composer, name: str) -> list[str] {
    c = g.resolve(name);
    if c is None {
        return [];
    }
    w = c spawn DescendantFlood(start_name=name);
    return sorted(w.reached);
}

"""True when ``descendant`` transitively depends on ``ancestor``."""
def depends_on(g: Composer, ancestor: str, descendant: str) -> bool {
    d = g.resolve(descendant);
    if d is None {
        return False;
    }
    w = d spawn DependenceProbe(target=ancestor);
    return w.found;
}

"""Parents + children + co-parents of ``name`` (sorted set, minus itself)."""
def markov_blanket(g: Composer, name: str) -> list[str] {
    if g.resolve(name) is None {
        return [];
    }
    claim: dict[str, bool] = {};
    for p in _parents_of(g, name) + _children_of(g, name) {
        claim[p] = True;
    }
    for child in _children_of(g, name) {
        for cop in _parents_of(g, child) {
            claim[cop] = True;
        }
    }
    claim.pop(name, None);
    return sorted(claim.keys());
}

source_code:
"""Causal graph: temporal cause-effect mapping over decision traces.

A CausalGraph records cause -> effect links between decision traces
(weighted, typed edges) and must stay a DAG: adding an edge that would
close a cycle is rejected up front by checking whether the cause is
already reachable from the effect. The hand-rolled version keeps
id-keyed adjacency maps, walks them with recursive DFS and color maps
for the cycle pre-check, and recomputes root/leaf lists by scanning all
nodes.
Ref: web3guru888/asi-build#280
"""
from collections import deque


def new_graph():
    return {"traces": {}, "succ": {}, "pred": {}}


def add_trace(graph, trace_id, phase):
    graph["traces"][trace_id] = phase


def _reachable(succ, start, target):
    seen = {start}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        for nxt in succ.get(cur, []):
            if nxt == target:
                return True
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return False


def add_cause(graph, cause_id, effect_id, weight=1.0):
    """Link cause -> effect; raises ValueError('causal_cycle') when the
    edge would close a cycle (cause already reachable from effect)."""
    if cause_id == effect_id or _reachable(graph["succ"], effect_id, cause_id):
        raise ValueError("causal_cycle")
    graph["succ"].setdefault(cause_id, []).append(effect_id)
    graph["pred"].setdefault(effect_id, []).append(cause_id)


def effects_of(graph, trace_id):
    """Transitive downstream effects of ``trace_id`` (exclusive), sorted."""
    seen = set()
    queue = deque([trace_id])
    while queue:
        cur = queue.popleft()
        for nxt in graph["succ"].get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return sorted(seen)


def causes_of(graph, trace_id):
    """Transitive upstream causes of ``trace_id`` (exclusive), sorted."""
    seen = set()
    queue = deque([trace_id])
    while queue:
        cur = queue.popleft()
        for nxt in graph["pred"].get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return sorted(seen)


def roots_and_leaves(graph):
    """(roots, leaves): traces with no causes / no effects. Sorted pair."""
    has_cause = set()
    has_effect = set()
    for c, effs in graph["succ"].items():
        has_effect.add(c)
        has_cause.update(effs)
    roots = sorted(t for t in graph["traces"] if t not in has_cause)
    leaves = sorted(t for t in graph["traces"] if t not in has_effect)
    return roots, leaves

candidate_osp_jac:
"""Causal graph, lifted to OSP.

Traces become nodes; cause -> effect links become a typed CausedBy edge
(with weight payload) mirrored by AffectedBy for upstream walks. The
recursive DFS cycle pre-check becomes one reachability flood spawned
from the effect: if it can already reach the cause, the edge would close
a cycle and the facade raises ValueError('causal_cycle'). Claim maps are
the explicit cycle policy -- jac walkers do not dedupe.
Ref: web3guru888/asi-build#280
"""
node Trace {
    has tid: str;
    has phase: str;
}
edge CausedBy {   # cause -> effect
    has weight: float;
}
edge AffectedBy {}  # effect -> cause (mirror)

"""Loader handle: trace ids resolve through this lookup map."""
obj CausalGraph {
    has traces: dict[str, Trace];
    has ids: list[str];

    def resolve(tid: str) -> Trace | None {
        return self.traces.get(tid);
    }
}

def new_graph() -> CausalGraph {
    return CausalGraph(traces={}, ids=[]);
}

def add_trace(graph: CausalGraph, trace_id: str, phase: str) -> None {
    t = Trace(tid=trace_id, phase=phase);
    root ++> t;
    graph.traces[trace_id] = t;
    graph.ids.append(trace_id);
}

walker CycleProbe {
    # Cycle policy: claim-once flood; stops early on hit via disengage
    # (single-probe walk, no sibling frontier to truncate).
    has claimed: dict[str, bool] = {};
    has target: str = "";
    has sink: HitFlag | None = None;

    can probe with Trace entry {
        if here.tid == self.target and self.sink is not None and not (self.sink.hit) {
            self.sink.hit = True;
            disengage;
        }
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        visit [->:CausedBy:->];
    }
}

obj HitFlag {
    has hit: bool = False;
}

"""Link cause -> effect; raises ValueError('causal_cycle') when the edge
would close a cycle."""
def add_cause(graph: CausalGraph, cause_id: str, effect_id: str, weight: float = 1.0) -> None {
    c: Trace = graph.traces[cause_id];
    e: Trace = graph.traces[effect_id];
    if cause_id == effect_id {
        raise ValueError("causal_cycle");
    }
    sink = HitFlag(hit=False);
    e spawn CycleProbe(claimed={}, target=cause_id, sink=sink);
    if sink.hit {
        raise ValueError("causal_cycle");
    }
    c +>:CausedBy(weight=weight):+> e;
    e +>:AffectedBy:+> c;
}

walker EffectFlood {
    has claimed: dict[str, bool] = {};
    has root_id: str = "";
    has found: list[str] = [];

    can step_effect with Trace entry {
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        if here.tid != self.root_id {
            self.found.append(here.tid);
        }
        visit [->:CausedBy:->];
    }
}

walker CauseClimb {
    has claimed: dict[str, bool] = {};
    has root_id: str = "";
    has found: list[str] = [];

    can step_cause with Trace entry {
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        if here.tid != self.root_id {
            self.found.append(here.tid);
        }
        visit [->:AffectedBy:->];
    }
}

"""Transitive downstream effects of ``trace_id`` (exclusive), sorted."""
def effects_of(graph: CausalGraph, trace_id: str) -> list[str] {
    start = graph.resolve(trace_id);
    if start is None {
        return [];
    }
    w = start spawn EffectFlood(claimed={}, root_id=trace_id);
    return sorted(w.found);
}

"""Transitive upstream causes of ``trace_id`` (exclusive), sorted."""
def causes_of(graph: CausalGraph, trace_id: str) -> list[str] {
    start = graph.resolve(trace_id);
    if start is None {
        return [];
    }
    w = start spawn CauseClimb(claimed={}, root_id=trace_id);
    return sorted(w.found);
}

"""(roots, leaves): traces with no causes / no effects. Sorted pair."""
def roots_and_leaves(graph: CausalGraph) -> tuple[list, list] {
    has_cause: dict[str, bool] = {};
    has_effect: dict[str, bool] = {};
    t: Trace;
    for tid in graph.ids {
        t = graph.traces[tid];
        downs = [t->:CausedBy:->];
        if len(downs) > 0 {
            has_effect[tid] = True;
        }
        for d in downs {
            has_cause[d.tid] = True;
        }
    }
    roots: list = [];
    leaves: list = [];
    for tid in graph.ids {
        if tid not in has_cause {
            roots.append(tid);
        }
        if tid not in has_effect {
            leaves.append(tid);
        }
    }
    return (sorted(roots), sorted(leaves));
}

