"""Task-tree cancel cascade with edge-owned lifetime and sweep.

Before-code synthesized from eumemic/aios#1152 (P1 cancel-cascade):
tasks own their children through parent links; ``cancel`` must cascade
revocation down the ACTIVE descendants (fulfilled tasks stay
terminal -- the fulfilled/revoked asymmetry), and a sweep pass detaches
terminated leaves so the tree carries no dead weight. The cascade here
collects the revocation set in one walk, then applies it outside the
walk.
"""

ACTIVE = "active"
FULFILLED = "fulfilled"
REVOKED = "revoked"


class TaskTree:
    def __init__(self):
        self.state = {}     # tid -> ACTIVE | FULFILLED | REVOKED
        self.parent = {}    # tid -> tid | None

    def spawn_task(self, parent_tid=None):
        if parent_tid is not None and parent_tid not in self.state:
            raise KeyError("unknown parent task")
        tid = "t%d" % (len(self.state) + 1)
        self.state[tid] = ACTIVE
        self.parent[tid] = parent_tid
        return tid

    def complete(self, tid):
        if tid not in self.state:
            raise KeyError("unknown task")
        if self.state[tid] == ACTIVE:
            self.state[tid] = FULFILLED
        return self.state[tid]

    def _children_map(self):
        children = {}
        for tid, p in self.parent.items():
            if p is not None:
                children.setdefault(p, []).append(tid)
        return children

    def cancel(self, tid):
        """Revoke ``tid`` and every active descendant; return count."""
        if tid not in self.state:
            raise KeyError("unknown task")
        # Phase 1 -- collect the revocation set in a single walk.
        to_revoke = []
        children = self._children_map()
        seen = set()
        frontier = [tid]
        while frontier:
            cur = frontier.pop()
            if cur in seen:
                continue
            seen.add(cur)
            if self.state[cur] == ACTIVE:
                to_revoke.append(cur)
            frontier.extend(children.get(cur, []))
        # Phase 2 -- apply outside the walk.
        for t in to_revoke:
            self.state[t] = REVOKED
        return len(to_revoke)

    def sweep(self):
        """Detach terminated leaf tasks; returns how many were removed."""
        children = self._children_map()
        removed = 0
        for tid in sorted(self.state):
            st = self.state[tid]
            if st == ACTIVE or tid not in self.state:
                continue
            if not children.get(tid):
                del self.state[tid]
                del self.parent[tid]
                removed += 1
        return removed

    def active_children(self, tid):
        """Sorted ids of active direct children of ``tid``."""
        kids = [t for t, p in self.parent.items() if p == tid]
        return sorted(t for t in kids if self.state[t] == ACTIVE)

    def active_descendants(self, tid):
        """Sorted ids of all active tasks below ``tid`` (inclusive)."""
        children = self._children_map()
        out = set()
        frontier = [tid]
        while frontier:
            cur = frontier.pop()
            if cur in out:
                continue
            if self.state.get(cur) == ACTIVE:
                out.add(cur)
            frontier.extend(children.get(cur, []))
        return sorted(out)

candidate_osp_jac:
"""Task-tree cancel cascade with edge-owned lifetime, lifted to OSP.

Tasks are ``Task`` nodes; parent ownership becomes typed ``Owns``
edges from parent to child. The cascade keeps the source's two-phase
protocol: a collect sweep gathers active descendants once per node
(explicit seen guard -- jac 0.36.1 has no built-in dedup), then the
façade applies revocation outside the walk. Fulfilled tasks stay
terminal (the fulfilled/revoked asymmetry); sweep detaches terminated
leaves by disconnecting their ``Owns`` edge and deleting the node.
"""

node Task {
    has tid: str;
    has state: str;
}

edge Owns: Task --> Task {}

node TaskRoot {}

glob ACTIVE: str = "active";
glob FULFILLED: str = "fulfilled";
glob REVOKED: str = "revoked";

"""Fresh tree root."""
def new_task_tree() -> TaskRoot {
    root ++> (r := TaskRoot());
    return r;
}

def _find_task(tree: TaskRoot, tid: str) -> Task | None {
    hits = [t for t in [tree -->][?:Task] if t.tid == tid];
    if len(hits) == 0 {
        return None;
    }
    return hits[0];
}

def _next_tid(tree: TaskRoot) -> str {
    all_t = [tree -->][?:Task];
    n = 1 + max([0] + [int(t.tid[1:]) for t in all_t]);
    return "t" + str(n);
}

"""Spawn a task under `parent_tid` (None for a root task); returns id."""
def spawn_task(tree: TaskRoot, parent_tid: str | None = None) -> str {
    tid = _next_tid(tree);
    root ++> (t := Task(tid=tid, state=ACTIVE));
    tree ++> t;
    if parent_tid is not None {
        p = _find_task(tree, parent_tid);
        if p is None {
            raise KeyError("unknown parent task");
        }
        p +>:Owns:+> t;
    }
    return tid;
}

"""Move an active task to fulfilled (terminal)."""
def complete(tree: TaskRoot, tid: str) -> str {
    t = _find_task(tree, tid);
    if t is None {
        raise KeyError("unknown task");
    }
    if t.state == ACTIVE {
        t.state = FULFILLED;
    }
    return t.state;
}

walker ActiveCollect {
    """Phase 1 of the cascade: gather active tasks once per node."""
    has claimed: dict[str, bool] = {};
    has to_revoke: list[str] = [];

    can step with Task entry {
        if here.tid in self.claimed {
            skip;
        }
        self.claimed[here.tid] = True;
        if here.state == ACTIVE {
            self.to_revoke.append(here.tid);
        }
        visit [->:Owns:->];
    }
}

"""Revoke `tid` and every active descendant; returns the count."""
def cancel(tree: TaskRoot, tid: str) -> int {
    t = _find_task(tree, tid);
    if t is None {
        raise KeyError("unknown task");
    }
    w = t spawn ActiveCollect();
    for x in w.to_revoke {
        node_ref = _find_task(tree, x);
        if node_ref is not None {
            node_ref.state = REVOKED;
        }
    }
    return len(w.to_revoke);
}

"""Detach terminated leaf tasks; returns how many were removed."""
def sweep(tree: TaskRoot) -> int {
    # Collect phase: find removable leaves without mutating mid-walk.
    doomed: list[Task] = [];
    for t in [tree -->][?:Task] {
        if t.state == ACTIVE {
            continue;
        }
        if len([t ->:Owns:->]) == 0 {
            doomed.append(t);
        }
    }
    removed = len(doomed);
    # Apply phase: disconnect from parent, then delete.
    for t in doomed {
        parents = [t ->:Owns:->];
        if len(parents) > 0 {
            t del ->:Owns:-> parents[0];
        } else {
            tree del --> t;
        }
        del t;
    }
    return removed;
}

"""Sorted ids of active direct children of `tid`."""
def active_children(tree: TaskRoot, tid: str) -> list[str] {
    t = _find_task(tree, tid);
    if t is None {
        raise KeyError("unknown task");
    }
    kids = [k for k in [t ->:Owns:->] if k.state == ACTIVE];
    return sorted(k.tid for k in kids);
}

walker ActiveSweep {
    """Gathers every active task below (and including) the start."""
