    if start not in w.states:
        return []
    seen: set[str] = set()
    stack: list[str] = [start]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in w.next_of.get(cur, []):
            if nxt not in seen:
                stack.append(nxt)
    return sorted(seen)


