    emitted: set[str] = set()
    visiting: set[str] = set()

    def _walk(name: str) -> None:
        if name in visiting:
            return
        if name in emitted:
            return
        if name not in g.messages:
            return
        visiting.add(name)
        emitted.add(name)
        for nxt in g.refs.get(name, []):
            _walk(nxt)
        visiting.discard(name)

    for r in roots:
        _walk(r)
    return sorted(emitted)


