                seen.add(blk)
                up_q.append(blk)
    down_q: deque[str] = deque([ticket_id])
    while down_q:
        cur = down_q.popleft()
        for nxt in board.blocks.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                down_q.append(nxt)
    return sorted(seen)

