    hits: list[str] = []
    stack = list(store._children.get(root, []))
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        hits.append(cur)
        for ch in store._children.get(cur, []):
            stack.append(ch)
    return hits


