        visited.add(node)
        stack.add(node)
        for nxt in graph._depends.get(node, []):
            if nxt in stack:
                errors.append((node, nxt))
            elif nxt not in visited:
                dfs(nxt)
        stack.remove(node)

    for ext in sorted(graph._extensions):
        if ext not in visited:
            dfs(ext)
    return sorted(errors)


