    if layer not in graph._layers:
        return []
    seen: set[str] = {layer}
    stack = [layer]
    while stack:
        cur = stack.pop()
        for nxt in graph._depends.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return sorted(seen)

