    if target not in store._parent_of:
        return []
    chain: list[str] = []
    cur: str | None = target
    seen: set[str] = set()
    while cur is not None:
        if cur in seen:
            break
        seen.add(cur)
        chain.append(cur)
        cur = store._parent_of.get(cur)
    rev = list(reversed(chain))
    return rev


def downstream_theorems(store: TheoremGraph, root: str) -> list[str]:
    if root not in store._parent_of:
        return []
    stack = [root]
    seen: set[str] = set()
    out: list[str] = []
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        out.append(cur)
        for ch in store._children_of.get(cur, []):
            stack.append(ch)
    return sorted(out)

