    if root not in store._parent_of:
        return []
    seen: set[str] = {root}
    queue: deque[str] = deque([root])
    while queue:
        cur = queue.popleft()
        for nxt in store._spawn_of.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
