    if root not in store._steps:
        return []
    seen: set[str] = {root}
    stack = [root]
    while stack:
        cur = stack.pop()
        for dep in store._depends.get(cur, []):
            if dep not in seen:
                seen.add(dep)
                stack.append(dep)
    return sorted(seen)

