    alts = store._calls.get(call_id, [])
    exact = _exact_object_alternatives(alts)
    if len(exact) == 1:
        return exact[0]
    return None


def receiver_outcome(store: CallStore, call_id: str) -> str:
    alts = store._calls.get(call_id, [])
    exact = _exact_object_alternatives(alts)
    if len(exact) == 1:
        return "exact"
    if len(exact) > 1:
        return "qualified"
    if any(a.startswith("obj:") for a in alts):
        return "qualified"
    if not alts:
        return "unavailable"
    return "unavailable"


