    if from_status not in store._statuses:
        return []
    seen: set[str] = set()
    queue: deque[str] = deque([from_status])
    while queue:
        cur = queue.popleft()
        for nxt in store._next.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return sorted(seen)


