from collections import deque
from typing import Any


def build_continuation_graph(facts: list[dict[str, Any]]) -> dict[str, Any]:
    adj: dict[str, list[str]] = {}
    parent: dict[str, str] = {}
    meta: dict[str, dict[str, Any]] = {}
    for fact in facts:
        fid = fact["id"]
        meta[fid] = fact
        adj.setdefault(fid, [])
        pid = fact.get("parent")
        if pid:
            adj.setdefault(pid, [])
            adj[pid].append(fid)
            parent[fid] = pid
    for node in adj:
        adj[node] = sorted(adj[node])
    return {"adj": adj, "parent": parent, "meta": meta}


def reachable_continuations(root: str, adj: dict[str, list[str]]) -> list[str]:
    seen: set[str] = set()
    order: list[str] = []
    queue: deque[str] = deque([root])
    while queue:
        cur = queue.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        order.append(cur)
        for nxt in adj.get(cur, []):
            queue.append(nxt)
    return order


def _apply_continuation(
    pf: tuple[Any, ...],
    pr: tuple[Any, ...] | None,
    fact: dict[str, Any],
) -> tuple[tuple[Any, ...], tuple[Any, ...] | None]:
    edge = fact.get("edge") or "then"
    if edge == "finally":
        return pf, pr
    if edge == "catch":
        if pr is not None:
            rf = fact.get("result_f")
            rr = fact.get("result_r")
            out_f = tuple(rf) if rf is not None else pf
            out_r = tuple(rr) if rr is not None else None
            return out_f, out_r
        return pf, pr
    if pr is None:
        rf = fact.get("result_f")
        if rf is not None:
            return (rf if isinstance(rf, tuple) else (rf,)), fact.get("result_r")
        return pf, pr
    rr = fact.get("result_r")
    if rr is not None:
