from collections import deque


class _ComponentNode:
    __slots__ = ("cid", "out")

    def __init__(self, cid: str) -> None:
        self.cid = cid
        self.out: list[_ComponentNode] = []


def _sorted_out(nd: _ComponentNode) -> list[_ComponentNode]:
