        return []
    claimed: dict[str, bool] = {}
    ids: list[str] = []
    stack: list[str] = [start_id]
    while stack:
        jid = stack.pop()
        if jid in claimed:
            continue
        claimed[jid] = True
        ids.append(jid)
        kids = _sorted_downstream(store, jid)
        i = len(kids) - 1
        while i >= 0:
            stack.append(kids[i])
            i -= 1
    return ids


