    order: list[str] = []
    total = len(indeg)
    while len(order) < total:
        ready = deque(jid for jid in sorted(indeg) if indeg[jid] == 0)
        if not ready:
            return None
        while ready:
            nid = ready.popleft()
            order.append(nid)
            for succ in store.downstream.get(nid, []):
                indeg[succ] -= 1
            indeg[nid] = -1
    return order


