}

def run_ray_recursive(
    plan: PlanGraph,
    upper: int
) -> list[int] {
    w = plan spawn RayPlanWalker(claimed={});
    values: list[int] = [];

    if upper <= 0 {
        return values;
    }
    if w.has_recursive_scan {
        if w.has_recurring_scan {
            current: int = 1;
            while current <= upper {
                values.append(current);
                current += 1;
            }
        }
    }
    return values;
}

