"""Competency Criteria Group removal with progress protection.

openedx/openedx-core#675 lifted to OSP: groups and criteria become
distinct archetypes under one typed Contains edge family; learner status
rows become ProgressOn cross-link edges. The depth cap is an ascent walk
counting ancestors; removal is two-phase -- a SubtreeFlood with a
once-only claim map collects the closure, the facade probes any incoming
ProgressOn link and then either flips archived flags or disconnects and
unregisters. Insertion order of Contains edges is preserved so the
per-group evaluation order stays observable.
"""
node GroupNode {
    has name: str;
    has archived: bool = False;
}
node CriterionNode {
    has name: str;
    has archived: bool = False;
}
node PersonNode { has learner_id: str; }
edge Contains {}
edge ProgressOn {}

"""Tree handle: id resolution through this lookup map is domain API."""
obj Mastery {
    has nodes: dict[str, GroupNode | CriterionNode];

    def resolve(name: str) -> Any {
        return self.nodes.get(name);
    }
}

def build_mastery(root_name: str) -> Mastery {
    m = Mastery(nodes={});
    g = GroupNode(name=root_name);
    root ++> g;
    m.nodes[root_name] = g;
    return m;
}

walker DepthAscent {
    has visited: dict[str, bool];
    has depth: int = 0;

    can step with GroupNode entry {
        if here.name in self.visited {
            skip;  # corrupt cycles stop climbing
        }
        self.visited[here.name] = True;
        parents: list[GroupNode] = [here <-:Contains:<-];
        if len(parents) == 0 {
            disengage;
        }
        self.depth += 1;
        visit [parents[0]];
    }
}

def add_group(m: Mastery, name: str, parent: str | None = None) {
    # source contract: unknown parent -> KeyError; criterion parent ->
    # ValueError("criteria are leaves"); duplicate names silently overwrite
    if parent is not None {
        p = m.resolve(parent);
        if p is None {
            raise KeyError("unknown parent");
        }
        if not isinstance(p, GroupNode) {
            raise ValueError("criteria are leaves");
        }
        w = p spawn DepthAscent(visited={});
        if w.depth + 1 >= 3 {
            raise ValueError("nesting exceeds depth 3");
        }
    } else {
        p = None;
    }
    g = m.resolve(name);
    if g is None or not isinstance(g, GroupNode) {
        # fresh registration (a stale criterion id gets replaced wholesale)
        old = m.nodes.pop(name, None);
        if old is not None {
            del old;
        }
        g = GroupNode(name=name);
        root ++> g;
        m.nodes[name] = g;
    }
    if parent is not None {
        # re-point under the (possibly new) parent
        for op in [g <-:Contains:<-] {
            op del ->:Contains:-> g;
        }
        p2 = m.resolve(parent);
        if p2 is not None {
            p2 +>:Contains:+> g;
        }
    }
}

def add_criterion(m: Mastery, name: str, parent_group: str) -> CriterionNode | None {
    p = m.resolve(parent_group);
    if p is None or not isinstance(p, GroupNode) {
        raise KeyError("unknown parent group");
    }
    c = CriterionNode(name=name);
    root ++> c;
    m.nodes[name] = c;
    p +>:Contains:+> c;
    return c;
}

def record_progress(m: Mastery, learner: str, criterion: str) -> CriterionNode | None {
    target = m.resolve(criterion);
    if target is None or not isinstance(target, CriterionNode) {
        raise KeyError("unknown criterion");
    }
    person = PersonNode(learner_id=learner);
    root ++> person;
    person +>:ProgressOn:+> target;
    return target;
}

"""Cross-link reachability: sorted learners touching any leaf below."""
def progress_in_subtree(m: Mastery, root_name: str) -> list[str] | None {
    start = m.resolve(root_name);
    if start is None {
        raise KeyError("unknown group");
    }
    w = start spawn SubtreeFlood(claimed={});
    people: list[str] = [];
    for n in w.found {
        if isinstance(n, CriterionNode) {
            learners: list[PersonNode] = [n <-:ProgressOn:<-];
            for p in learners {
                if p.learner_id not in people {
                    people.append(p.learner_id);
                }
            }
        }
    }
    return sorted(people);
}

"""Insertion order within this group only -- the evaluation order."""
def list_criteria_ordered(m: Mastery, group: str) -> list[str] | None {
    g = m.resolve(group);
    if g is None or not isinstance(g, GroupNode) {
        raise KeyError("unknown group");
    }
    out: list[str] = [];
    kids: list[GroupNode | CriterionNode] = [g ->:Contains:->];
    for k in kids {
        if isinstance(k, CriterionNode) and not k.archived {
            out.append(k.name);
        }
    }
    return out;
}

"""Two-phase removal: archive-only once any progress exists below."""
def remove_group(m: Mastery, root_name: str) -> dict {
    start = m.resolve(root_name);
    if start is None or not isinstance(start, GroupNode) {
        raise KeyError("unknown group");
    }
    # Phase 1: collect closure + probe progress links.
    w = start spawn SubtreeFlood(claimed={});
    doomed_names: list[str] = [start.name];
    for n in w.found {
        if n.name != start.name {
            doomed_names.append(n.name);
        }
    }
    affected = progress_in_subtree(m, root_name);
    result: dict = {"fate": "deleted", "removed": []};
    if affected is not None and len(affected) > 0 {
        result["fate"] = "archived";
        # apply outside collection: flip flags only, data preserved
        for n in w.found {
            n.archived = True;
        }
    } else {
        parents: list[GroupNode] = [start <-:Contains:<-];
        if len(parents) > 0 {
            par = parents[0];
            par del ->:Contains:-> start;
        }
        for name in doomed_names {  # unregister outside the walk
            m.nodes.pop(name, None);
        }
    }
    ordered = sorted(doomed_names);
    result["removed"] = ordered;
    return result;
}

def live_nodes(m: Mastery) -> list[str] {
    out: list[str] = [];
    keys: list[str] = [];
    for k in m.nodes.keys() {
        keys.append(k);
    }
    for k in sorted(keys) {
        nd = m.resolve(k);
        if isinstance(nd, GroupNode) {
            if not nd.archived {
                out.append(k);
            }
        } elif isinstance(nd, CriterionNode) {
            if not nd.archived {
                out.append(k);
            }
        }
    }
    return out;
}

"""Floods Contains edges; once-only claim map is the cycle policy."""
walker SubtreeFlood {
    has claimed: dict[str, bool];
    has found: list[GroupNode | CriterionNode] = [];

    can step with GroupNode entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here);
        visit [->:Contains:->];
    }

    can step_leaf with CriterionNode entry {
        if here.name in self.claimed {
            skip;
        }
        self.claimed[here.name] = True;
        self.found.append(here);
    }
}

floor_jac:
"""Competency Criteria Group removal with progress protection.

Before-code synthesized from openedx/openedx-core#675: a competency's
mastery rule is an unbounded tree of criterion groups holding leaf
criteria; removal must take the WHOLE subtree. Hard delete is allowed
only while NO learner status row exists anywhere beneath the target --
once any exists the branch becomes archive-only. Authoring caps nesting
at depth 3. Groups keep parent pointers and children adjacency maps;
learner progress is a many-to-many link map walked when deciding fate.
Criteria keep their insertion order per group -- mastery rules evaluate
in that order, so it is observable domain data, not an implementation
detail.
"""
with entry {
    MAX_DEPTH = 3;
}
"""Authoring forbids nesting deeper than three group levels."""
class DepthError(ValueError) {}
class CompetencyTree {
    def init(self: CompetencyTree)  -> Any {
        self.kind_of = {};
        self.parent_of = {};
        self.children_of = {};
        self.archived = `set();
        self.progress = {};
    }
    def _depth_of(self: CompetencyTree, name: Any)  -> int {
        depth = 0;
        seen = {name};
        cur = self.parent_of.get(name);
        while (cur is not None) {
            if (cur in seen) {
                break;
            }
            seen.add(cur);
            depth += 1;
            cur = self.parent_of.get(cur);
        }
        return depth;
    }
    """Groups nest; the backend enforces the depth cap."""
    def add_group(self: CompetencyTree, name: Any, parent: Any = None)  -> Any {
        if ((parent is not None) and (parent not in self.parent_of)) {
            raise KeyError("unknown parent");
        }
        if ((parent is not None) and (self.kind_of[parent] != "group")) {
            raise ValueError("criteria are leaves");
        }
        if ((parent is not None) and ((self._depth_of(parent) + 1) >= int(MAX_DEPTH))) {
            raise DepthError(("nesting exceeds depth %d" % MAX_DEPTH));
        }
        self.kind_of[name] = "group";
        self.parent_of[name] = parent;
        if (parent is not None) {
            self.children_of.setdefault(parent, []).append(name);
        }
        self.children_of.setdefault(name, []);
        return True;
    }
    def add_criterion(self: CompetencyTree, name: Any, parent_group: Any)  -> Any {
        if (parent_group not in self.kind_of) {
            raise KeyError("unknown parent group");
        }
        if (self.kind_of[parent_group] != "group") {
            raise ValueError("criteria are leaves");
        }
        self.kind_of[name] = "criterion";
        self.parent_of[name] = parent_group;
        self.children_of.setdefault(parent_group, []).append(name);
        return True;
    }
    def record_progress(self: CompetencyTree, learner: Any, criterion: Any)  -> Any {
        if (self.kind_of.get(criterion) != "criterion") {
            raise KeyError("unknown criterion");
        }
        self.progress.setdefault(learner, `set()).add(criterion);
    }
    def _subtree(self: CompetencyTree, `root: Any)  -> Any {
        out = [];
        stack = [`root];
        seen = `set();
        while stack {
            cur = stack.pop();
            if (cur in seen) {
                continue;
            }
            seen.add(cur);
            out.append(cur);
            stack.extend(self.children_of.get(cur, []));
        }
        return out;
    }
    """Cross-link reachability: learners touching any leaf below."""
    def progress_in_subtree(self: CompetencyTree, `root: Any)  -> Any {
        nodes = `set(self._subtree(`root));
        learners = [];
        for (learner, crits) in self.progress.items() {
            if (crits & nodes) {
                learners.append(learner);
            }
        }
        return sorted(learners);
    }
    """Remove the whole subtree; archive-only once progress exists.

        Two-phase: collect the closure and probe progress first, then
        apply either archival flips or hard removal. Returns a tuple of
        (fate, affected_node_names_sorted).
        """
    def remove_group(self: CompetencyTree, `root: Any)  -> Any {
        if (self.kind_of.get(`root) != "group") {
            raise KeyError("unknown group");
        }
        doomed = sorted(list(self._subtree(root)));
        touched = self.progress_in_subtree(`root);
        if touched {
            for n in doomed {
                self.archived.add(n);
            }
            return ("archived", doomed);
        }
        parent = self.parent_of.get(`root);
        if (parent is not None) {
            self.children_of[parent] = [
                c
                for c in self.children_of.get(parent, [])
                if (c != `root)
            ];
        }
        for n in doomed {
            self.kind_of.pop(n, None);
            self.parent_of.pop(n, None);
            self.children_of.pop(n, None);
            self.archived.discard(n);
        }
        return ("deleted", doomed);
    }

    """Insertion order within this group only (evaluation order)."""
    def list_criteria_ordered(self: CompetencyTree, group: Any)  -> Any {
        out = [];
        for child in list(self.children_of.get(group, [])) {
            if (
                (self.kind_of.get(child) == "criterion")
                and (child not in self.archived)
            ) {
                out.append(child);
            }
        }
        return out;
    }
    def live_nodes(self: CompetencyTree)  -> Any {
        return sorted(
            n
            for n in self.kind_of
            if (n not in self.archived)
        );
    }
}

candidate_osp_jac:
"""Comment hard delete: scoped walk vs unscoped FK cascade accounting.

autumn-foundation/autumn#2275 lifted to OSP: comments become CommentNode
archetypes carrying their record scope; reply links become typed
ChildComment edges walked in both directions. The scoped walk prunes at
the record boundary while the unscoped flood follows every edge exactly
like ON DELETE CASCADE does -- the spill between them is the defect.
Deletion is two-phase: collect reach + depth levels with once-only claim
maps, then decrement EVERY affected record's counter and disconnect +
unregister outside the walks.
"""
node CommentNode {
    has cid: str;
    has scope: str;   # "(type,id)" record key
}
edge ChildComment {}

"""Store handle: id resolution plus live per-record counters."""
obj Store {
    has comments: dict[str, CommentNode];
    has counts: dict[str, int];

    def resolve(cid: str) -> CommentNode | None {
        return self.comments.get(cid);
    }
}

def build_store() -> Store {
    return Store(comments={}, counts={});
}

def _register(st: Store, cid: str, scope: str, parent_id: str | None) {
    cn = CommentNode(cid=cid, scope=scope);
    root ++> cn;
    st.comments[cid] = cn;
    if parent_id is not None {
        p = st.resolve(parent_id);
        if p is not None {
            p +>:ChildComment:+> cn;
        }
    }
    cur = st.counts.get(scope, 0);
    st.counts[scope] = cur + 1;
}

"""Framework write path: replies must stay inside the record."""
def add_comment(st: Store, cid: str, scope: str, parent_id: str | None = None) {
    if parent_id is not None {
        p = st.resolve(parent_id);
        if p is None {
            raise KeyError("unknown parent");
        }
        if p.scope != scope {
            raise ValueError("reply crosses record boundary");
        }
    }
    _register(st, cid, scope, parent_id);
}

"""Imported row: may legally carry a CROSS-RECORD parent link."""
def import_comment(st: Store, cid: str, scope: str, parent_id: str | None) {
    if parent_id is not None and st.resolve(parent_id) is None {
        raise KeyError("unknown parent");
    }
    _register(st, cid, scope, parent_id);
}

"""Flood over child edges; prune at other-record nodes when scoped."""
walker ReachFlood {
    has claimed: dict[str, bool];
    has found: list[CommentNode] = [];
    has only_scope: str | None = None;

    can step with CommentNode entry {
        if here.cid in self.claimed {
            skip;
        }
        self.claimed[here.cid] = True;
        if self.only_scope is not None and here.scope != self.only_scope {
            return;  # prune at the record boundary
        }
        self.found.append(here);
        visit [->:ChildComment:->];
    }
}

def scoped_subtree(st: Store, cid: str) -> list[str] | None {
    start = st.resolve(cid);
    if start is None {
        raise KeyError("unknown comment");
    }
    w = start spawn ReachFlood(claimed={}, only_scope=start.scope);
    out: list[str] = [];
    for n in w.found {
        out.append(n.cid);
    }
    return sorted(out);
}

def unscoped_cascade_reach(st: Store, cid: str) -> list[str] | None {
    start = st.resolve(cid);
    if start is None {
        raise KeyError("unknown comment");
    }
    w = start spawn ReachFlood(claimed={});
    out: list[str] = [];
    for n in w.found {
        out.append(n.cid);
    }
    return sorted(out);
}

"""Rows the DB removes but the scoped query never reported."""
def spill_set(st: Store, cid: str) -> list[str] | None {
    scoped = scoped_subtree(st, cid);
    reach = unscoped_cascade_reach(st, cid);
    if scoped is None or reach is None {
        return None;
    }
    spill: list[str] = [];
    for c in reach {
        if c not in scoped {
            spill.append(c);
        }
    }
    return sorted(spill);
}

"""Depth levels of the same-record replies below ``cid``."""
walker HopSameRecord {
    has claimed: dict[str, bool];
    has scope: str;
    has found: list[CommentNode] = [];

    can step with CommentNode entry {
        kids: list[CommentNode] = [here ->:ChildComment:->];
        for k in kids {
            if k.cid in self.claimed or k.scope != self.scope {
                continue;
            }
            self.claimed[k.cid] = True;
            self.found.append(k);
        }
    }
}

"""Honest two-phase delete with per-record counter repair."""
def hard_delete_subtree(st: Store, cid: str) -> dict {
    start = st.resolve(cid);
    if start is None {
        raise KeyError("unknown comment");
    }
    # Phase 1: collect reach + spill + depth report (read-only walks).
    w = start spawn ReachFlood(claimed={});
    reach = w.found;
    scoped_n = 0;
    spill_n = 0;
    per_record: dict[str, int] = {};
    for n in reach {
        cur = st.counts.get(n.scope, 0);
        if n.scope == start.scope {
            scoped_n += 1;
        } else {
            spill_n += 1;
        }
        per_record[n.scope] = per_record.get(n.scope, 0) + 1;
    }
    claimed: dict[str, bool] = {cid: True};
    levels: list[int] = [];
    frontier: list[CommentNode] = [start];
    while len(frontier) > 0 {
        nxt: list[CommentNode] = [];
        for f in frontier {
            hw = f spawn HopSameRecord(claimed=claimed, scope=start.scope, found=nxt);
            nxt = hw.found;
        }
        if len(nxt) == 0 {
            break;
        }
        levels.append(len(nxt));
        frontier = nxt;
    }
    # Phase 2: sever spill roots, fix counters, unregister everything.
    for n in reach {
        parents: list[CommentNode] = [n <-:ChildComment:<-];
        if len(parents) > 0 {
            par = parents[0];
            if par.cid not in st.comments.keys() or par.cid == cid {
                continue;
            }
            par del ->:ChildComment:-> n;
        }
    }
    for scope_key in per_record.keys() {
        st.counts[scope_key] = st.counts.get(scope_key, 0) - per_record[scope_key];
    }
    for n in reach {
        st.comments.pop(n.cid, None);
    }
    return {"scoped": scoped_n, "total": len(reach), "spill": spill_n, "levels": levels};
}

floor_jac:
"""Comment hard delete: scoped walk vs unscoped FK cascade accounting.

Before-code synthesized from autumn-foundation/autumn#2275: deleting a
comment subtree collects descendants by ``parent_id`` filtered to one
record scope ``(commentable_type, commentable_id)`` -- but the database's
ON DELETE CASCADE is NOT so scoped. An imported row can name a comment in
this subtree as parent while belonging to ANOTHER record: it vanishes
without appearing in the count and silently corrupts that other record's
comment counter. The fix computes the true cascade reach first (ignoring
scope), decrements every affected record by its own share, and reports an
honest total. Children adjacency maps per record; the unscoped reach is a
plain stack walk over the global child map. Reply depth levels are part
of the deletion report.
"""
"""A cross-record edge was detected where policy forbids it."""
class CrossRecordError(ValueError) {}
class CommentStore {
    def init(self: CommentStore)  -> Any {
        self.parent_of = {};
        self.children_of = {};
        self.record_of = {};
        self.counts = {};
    }
    def _register(self: CommentStore, cid: Any, record: Any, parent_id: Any)  -> Any {
        self.record_of[cid] = record;
        self.parent_of[cid] = parent_id;
        if (parent_id is not None) {
            self.children_of.setdefault(parent_id, []).append(cid);
        }
        self.children_of.setdefault(cid, []);
        self.counts[record] = self.counts.get(record, 0) + 1;
    }
    """Framework write path: replies must stay inside the record."""
    def add_comment(
        self: CommentStore, cid: Any, record: Any, parent_id: Any = None
    ) {
        if (parent_id is not None) {
            if (parent_id not in self.parent_of) {
                raise KeyError("unknown parent");
            }
            if (self.record_of[parent_id] != record) {
                raise CrossRecordError("reply crosses record boundary");
            }
        }
        self._register(cid, record, parent_id);
    }
    """Imported/migrated row: may carry a CROSS-RECORD parent link.

        This is exactly the shape issue #2275 warns about -- legal at the
        storage layer even though the write path can never produce it.
        """
    def import_comment(
        self: CommentStore, cid: Any, record: Any, parent_id: Any
    ) {
        if ((parent_id is not None) and (parent_id not in self.parent_of)) {
            raise KeyError("unknown parent");
        }
        self._register(cid, record, parent_id);
    }

    """Stack walk over the global child map.

        ``scoped_to`` prunes at comments outside that record; ``None``
        follows every edge like the raw FK cascade does.
        """
    def _walk(self: CommentStore, start: Any, scoped_to: Any = None)  -> Any {
        out = [];
        stack = [start];
        seen = `set();
        while stack {
            cur = stack.pop();
            if (cur in seen) {
                continue;
            }
            seen.add(cur);
            if ((scoped_to is not None) and (self.record_of[cur] != scoped_to)) {
                continue;
            }
            out.append(cur);
            stack.extend(self.children_of.get(cur, []));
        }
        return out;
    }

    """What the recursive query collects: same-record replies only."""
    def scoped_subtree(self: CommentStore, cid: Any)  -> Any {
        return sorted(list(self._walk(cid, scoped_to=self.record_of[cid])));
    }
    """What ON DELETE CASCADE actually removes: everything reachable."""
    def unscoped_cascade_reach(self: CommentStore, cid: Any)  -> Any {
        return sorted(list(self._walk(cid)));
    }
    """Rows the DB removes but the scoped query never reported."""
    def spill_set(self: CommentStore, cid: Any)  -> Any {
        scoped = `set(self.scoped_subtree(cid));
        allreach = `set(self.unscoped_cascade_reach(cid));
        return sorted((allreach - scoped));
    }
    """Honest two-phase delete with per-record counter repair.

        Phase 1 collects scoped ids + spill + depth report; phase 2
        applies removal and fixes EVERY affected record's counter.
        Returns {"scoped": n, "total": m, "levels": [...]}.
        """
    def hard_delete_subtree(self: CommentStore, cid: Any)  -> Any {
        root_record = self.record_of[cid];
        reach = self._walk(cid);
        scoped = [
            c
            for c in reach
            if (self.record_of[c] == root_record)
        ];
        spill = [
            c
            for c in reach
            if (self.record_of[c] != root_record)
        ];
        levels = [];
        frontier = [cid];
        seen = {cid};
        while frontier {
            nxt = [];
            for cur in frontier {
                for ch in list(self.children_of.get(cur, [])) {
                    if ((ch in seen) or (self.record_of[ch] != root_record)) {
                        continue;
                    }
                    seen.add(ch);
                    nxt.append(ch);
                }
            }
            if nxt {
                levels.append(nxt);
            }
            frontier = nxt;
        }
        per_record = {};
        for c in reach {
            rec = self.record_of[c];
            per_record[rec] = per_record.get(rec, 0) + 1;
        }
        for (rec, cnt) in per_record.items() {
            self.counts[rec] = self.counts.get(rec, 0) - cnt;
        }
        removed = `set(reach);
        for c in reach {
            p = self.parent_of.get(c);
            if ((p is not None) and (p not in removed)) {
                self.children_of[p] = [
                    x
                    for x in self.children_of.get(p, [])
                    if (x != c)
                ];
            }
            self.children_of.pop(c, None);
            self.parent_of.pop(c, None);
            self.record_of.pop(c, None);
        }
        out_rep: dict = dict();
        out_rep["scoped"] = len(list(scoped));
        out_rep["total"] = len(list(reach));
        out_rep["spill"] = len(list(spill));
        out_rep["levels"] = [len(l) for l in levels];
        return out_rep;
    }
}

source_code:
"""Tag taxonomy: subset hierarchy, effective membership and cleanup sweeps.

Before-code synthesized from bestofjs/bestofjs#485: a tag may declare one
parent meaning "every project with this tag is by definition tagged with
the parent" (nextjs -> react). Effective membership therefore closes over
ancestor chains, while the catalog still stores redundant direct tags --
a project tagged both ``nextjs`` and ``react`` does not need the ``react``
row anymore. Reparenting must reject cycles at write time, and after any
reparent a cleanup sweep drops now-redundant direct tags per project,
decrementing each tag's stored usage count exactly once. Parent pointers
for tags, an id-keyed membership map for projects, and hand-rolled walks
everywhere.
"""


class CycleError(ValueError):
    """Setting that parent would create a cycle."""


class TagTaxonomy:
    def __init__(self):
        self.parent_of = {}     # tag -> parent | None
        self.facet_of = {}      # tag -> "ecosystem" | "category" | ...
        self.tags_of = {}       # project -> set of directly stored tags
        self.usage = {}         # tag -> number of projects storing it

    def add_tag(self, name, parent=None, facet=None):
        if parent is not None and parent not in self.parent_of:
            raise KeyError("unknown parent tag")
        if parent == name:
            raise CycleError("self parent")
        self.parent_of[name] = parent
        self.facet_of[name] = facet
        self.usage.setdefault(name, 0)

    def _ancestors(self, tag):
        chain = []
        seen = {tag}
        cur = self.parent_of.get(tag)
        while cur is not None:
            if cur in seen:
                break  # tolerate corrupt cycles on read paths
            seen.add(cur)
            chain.append(cur)
            cur = self.parent_of.get(cur)
        return chain

    def _descendants(self, tag):
        out = []
        stack = [tag]
        seen = set()
        while stack:
            cur = stack.pop()
            if cur in seen:
                continue
            seen.add(cur)
            if cur != tag:
