    uses: list[tuple[str, str]],
    composite: set[str],
) -> list[str]:
    seen: set[str] = set()
    for seed in sorted(seeds):
        for item in follow_local_uses(seed, uses, composite):
            seen.add(item)
    return sorted(seen)

