        store._assets.discard(aid)
        store._derivatives.pop(aid, None)
        store._scene_refs.pop(aid, None)
        for refs in store._scene_refs.values():
            if aid in refs:
                refs.remove(aid)
        for kids in store._derivatives.values():
            if aid in kids:
                kids.remove(aid)
    return deleted


