    seen: set[str] = set()
    q: deque[str] = deque(seed_phases)
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for dep in g._phase_deps.get(cur, []):
            if dep not in seen:
                q.append(dep)
    return sorted(seen)

