    out: list[str] = [];
    for loc in up.hits {
        if loc.loc_id in seen_locs {
            continue;
        }
        seen_locs[loc.loc_id] = True;
        encs: list[Encounter] = [loc <-:At:<-];
        for enc in encs {
            out.append(enc.enc_id);
        }
    }
    for loc in down.hits {
        if loc.loc_id in seen_locs {
            continue;
        }
        seen_locs[loc.loc_id] = True;
        encs2: list[Encounter] = [loc <-:At:<-];
        for enc in encs2 {
            out.append(enc.enc_id);
        }
    }
    return sorted(out);
}

"""Role-based access control, lifted to OSP.

Roles become Role nodes carrying their grant and deny lists, and the
parent_id chain becomes a typed Extends edge (child to parent). The
while-loop chain walk and merge become a walker over Extends edges: each
role has exactly one parent, so step order is the chain order nearest
first, and first-mention-wins (deny beating allow within one role)
reproduces the nearest-mention override exactly. The claim map is the
malformed-hierarchy cycle policy; output stays sorted.
Ref: TheSyriableDev/fiverr#30
"""
node Role {
    has rid: str;
    has grants: list[str];
    has denies: list[str];
}
edge Extends {}

"""Loader handle: role ids resolve through this lookup map."""
obj RoleBook {
    has roles: dict[str, Role];

    def resolve(rid: str) -> Role | None {
        return self.roles.get(rid);
    }
}

"""Deterministic fresh-graph builder from role rows in any order."""
def load_roles(roles: list[dict]) -> RoleBook {
    rb = RoleBook(roles={});
    for row in roles {
        r = Role(rid=row["id"], grants=row["permissions"], denies=row["denied"]);
        root ++> r;
        rb.roles[row["id"]] = r;
    }
    for row in roles {
        pid = row.get("parent_id");
        if pid is not None {
            child = rb.roles.get(row["id"]);
            parent = rb.roles.get(pid);
            if child is None {
                continue;
            }
            if parent is None {
                continue;  # dangling parent_id: chain stops after the role
            }
            child +>:Extends:+> parent;
        }
    }
    return rb;
}

walker InheritWalk {
    has claimed: dict[str, bool] = {};
    has decided: dict[str, bool] = {};

    can step with Role entry {
        # Cycle policy: one visit per role (malformed-hierarchy guard).
        if here.rid in self.claimed {
            skip;
        }
        self.claimed[here.rid] = True;
        # Nearest mention wins: this role is closer than its ancestors,
        # and within one role a deny beats an allow.
        for p in here.denies {
            if p not in self.decided {
                self.decided[p] = False;
            }
        }
        for p in here.grants {
            if p not in self.decided {
                self.decided[p] = True;
            }
        }
        visit [->:Extends:->];
    }
}

"""Sorted list of effective grants for ``role`` (nearest mention wins)."""
def effective_permissions(roles: list[dict], role: str) -> list {
    rb = load_roles(roles);
    start = rb.resolve(role);
    if start is None {
        return [];
    }
    w = start spawn InheritWalk(claimed={}, decided={});
    out: list[str] = [];
    for p in w.decided.keys() {
        if w.decided[p] {
            out.append(p);
        }
    }
    return sorted(out);
}

"""True iff ``perm`` is an effective grant of ``role``."""
def can(roles: list[dict], role: str, perm: str) -> bool {
    return perm in effective_permissions(roles, role);
}

floor_jac:
"""Role-based access control with inherited permissions.

Roles form a hierarchy (Guest -> Buyer -> Seller -> Admin -> SuperAdmin)
via ``parent_id`` pointers: ``effective_permissions`` walks up the chain
with a while loop and merges grants, where the NEAREST mention of a
permission wins — a role nearer the queried role overrides what its
ancestors say, and when one role mentions a permission in both its
``denied`` and ``permissions`` lists, the deny wins. Effective grants
are returned sorted.
Ref: TheSyriableDev/fiverr#30
"""
"""Sorted list of effective grants for ``role``.

    ``roles`` is a list of ``{"id": ..., "parent_id": ...,
    "permissions": [...], "denied": [...]}`` rows in any order. The
    chain from ``role`` upward is walked nearest first; the first role
    in the chain to mention a permission decides it, deny beating allow
    within a single role. An unknown ``role`` has no grants.
    """
def effective_permissions(roles: Any, role: Any) -> object {
    by_id: dict = {r["id"]: r for r in roles};
    chain: list = [];
    cur = by_id.get(role);
    while (cur is not None) {
        chain.append(cur);
        pid = cur.get("parent_id");
        cur = by_id.get(pid) if (pid is not None) else None;
    }
    decided: dict = {};
    for r in chain {
        for p in r["denied"] {
            decided.setdefault(p, False);
        }
        for p in r["permissions"] {
            decided.setdefault(p, True);
        }
    }
    return sorted(
        p
        for (p, ok) in decided.items()
        if ok
    );
}

"""True iff ``perm`` is an effective grant of ``role``."""
def `can(roles: Any, role: Any, perm: Any) -> object {
    return (perm in effective_permissions(roles, role));
}

