"""Multi-hop reasoning over a memory relationship graph.

The memory store keeps memories as a flat list plus a link list of
``(from, to, kind, strength)`` records with kinds ``references``,
``contradicts``, ``builds_on``, ``caused_by``, ``similar_to`` and
``part_of``. The knowledge-graph integration needs to discover
relationships and reason across hops ("memories related to memories
about X") and to detect contradictions, so the flat store grows a
hand-rolled adjacency dict and a deque BFS: ``related_within`` collects
every memory within ``hops`` links of a starting memory (links navigated
in both directions -- a relationship relates both memories), and
``contradiction_pairs`` lists the canonical contradictory pairs.
Unknown memory ids inside links are skipped; an unknown starting id
raises KeyError.
Ref: DollhouseMCP/mcp-server#337
"""

from collections import deque


def related_within(store, mid, hops=2):
    """Memory ids within ``hops`` links of ``mid`` (itself excluded), sorted.

    Breadth-first over the undirected view of the link list; each memory
    counts at its shortest link distance, so a memory reachable through
    any chain of at most ``hops`` links is included, and link cycles
    cannot loop the queue (the distance map is the visited set).
    """
    adj = {}
    for frm, to, kind, strength in store["links"]:
        if frm in store["memories"] and to in store["memories"]:
            adj.setdefault(frm, []).append(to)
            adj.setdefault(to, []).append(frm)
    if mid not in store["memories"]:
        raise KeyError(mid)
    dist = {mid: 0}
    queue = deque([mid])
    while queue:
        cur = queue.popleft()
        if dist[cur] >= hops:
            continue
        if cur not in adj:
            continue
        for nbr in list(adj[cur]):
            if nbr not in dist:
                dist[nbr] = dist[cur] + 1
                queue.append(nbr)
    return sorted(x for x in dist if x != mid)


def contradiction_pairs(store):
    """Canonical contradictory pairs ``[[a, b], ...]`` with a < b, sorted.

    One entry per distinct ``contradicts`` link, direction ignored.
    """
    pairs = set()
    for frm, to, kind, strength in store["links"]:
        if kind != "contradicts":
            continue
        if frm not in store["memories"] or to not in store["memories"]:
            continue
        pairs.add((frm, to) if frm < to else (to, frm))
    return sorted([a, b] for a, b in pairs)

candidate_osp_jac:
"""Memory relationships lifted to OSP.

Memories become Memory nodes; every relationship record becomes one Rel
edge archetype carrying its kind and strength payload (the link list is
homogeneous apart from the kind string, so a single payload edge beats
six edge types -- documented design choice), inserted in BOTH directions
because the store's relationships are navigable either way. The deque
BFS over the adjacency dict becomes a shortest-chain relaxation walker
whose claim map doubles as the cycle guard, and whose hop budget is the
multi-hop reasoning bound. ``contradiction_pairs`` stays a link filter:
in the source it never traverses, it canonicalizes contradicts records.
Ref: DollhouseMCP/mcp-server#337
"""
node Memory {
    has mid: str;
}
edge Rel {
    has kind: str;
    has strength: float;
}

"""Loader handle: memory ids resolve through this lookup map."""
obj MemStore {
    has mems: dict[str, Memory];

    def resolve(mid: str) -> Memory | None {
        return self.mems.get(mid);
    }
}

"""Deterministic fresh-graph builder; creation order = fixture order."""
def load_store(store: dict) -> MemStore {
    ms = MemStore(mems={});
    for m in list(store["memories"]) {
        n = Memory(mid=str(m));
        root ++> n;
        ms.mems[str(m)] = n;
    }
    for link in list(store["links"]) {
        frm = ms.resolve(str(link[0]));
        to = ms.resolve(str(link[1]));
        if frm is None or to is None {
            continue;  # unknown memory ids in links are skipped
        }
        kind = str(link[2]);
        strength = float(str(link[3]));
        frm +>:Rel(kind=kind, strength=strength):+> to;
        to +>:Rel(kind=kind, strength=strength):+> frm;
    }
    return ms;
}

walker NearWalk {
    # Cycle policy: claim map keyed by memory id (jac walkers do not
    # dedupe). A non-improving revisit skips; a strictly shallower arrival
    # re-expands, so the map ends holding each memory's shortest link
    # distance -- the multi-hop neighborhood within the hop budget, with
    # link loops terminating on the claim map.
    has best: dict[str, int] = {};
    has hops: int = 0;
    has budget: int = 2;

    can step with Memory entry {
        if here.mid in self.best and self.hops >= self.best[here.mid] {
            skip;
        }
        self.best[here.mid] = self.hops;
        if self.hops < self.budget {
            for nbr in [here->:Rel:->] {
                nbr spawn NearWalk(best=self.best, hops=self.hops + 1, budget=self.budget);
            }
        }
    }
}

"""Memory ids within ``hops`` links of ``mid`` (itself excluded), sorted."""
def related_within(store: dict, mid: str, hops: int = 2) -> list[str] {
    ms = load_store(store);
    start = ms.resolve(mid);
    if start is None {
        raise KeyError(mid);
    }
    w = start spawn NearWalk(best={}, hops=0, budget=hops);
    out: list[str] = [];
    for k in w.best.keys() {
        if k != mid and w.best[k] <= hops {
            out.append(k);
        }
    }
    return sorted(out);
}

"""Canonical contradictory pairs ``[[a, b], ...]`` with a < b, sorted."""
def contradiction_pairs(store: dict) -> list {
    # a filter over the link records, not a traversal: no walk in the
    # source, none here
    pairs: set[str] = set();
    mems: set[str] = set();
    for m in list(store["memories"]) {
        mems.add(str(m));
    }
    for link in list(store["links"]) {
        if str(link[2]) != "contradicts" {
            continue;
        }
        frm = str(link[0]);
        to = str(link[1]);
        if frm not in mems or to not in mems {
            continue;
        }
        if frm < to {
            pairs.add(frm + "|" + to);
        } else {
            pairs.add(to + "|" + frm);
        }
    }
    out: list = [];
    for p in sorted(pairs) {
        out.append(p.split("|"));
    }
    return out;
}

floor_jac:
"""Multi-hop reasoning over a memory relationship graph.

The memory store keeps memories as a flat list plus a link list of
``(from, to, kind, strength)`` records with kinds ``references``,
``contradicts``, ``builds_on``, ``caused_by``, ``similar_to`` and
``part_of``. The knowledge-graph integration needs to discover
relationships and reason across hops ("memories related to memories
about X") and to detect contradictions, so the flat store grows a
hand-rolled adjacency dict and a deque BFS: ``related_within`` collects
every memory within ``hops`` links of a starting memory (links navigated
in both directions -- a relationship relates both memories), and
``contradiction_pairs`` lists the canonical contradictory pairs.
Unknown memory ids inside links are skipped; an unknown starting id
raises KeyError.
Ref: DollhouseMCP/mcp-server#337
"""
import from collections { deque }
"""Memory ids within ``hops`` links of ``mid`` (itself excluded), sorted.

    Breadth-first over the undirected view of the link list; each memory
    counts at its shortest link distance, so a memory reachable through
    any chain of at most ``hops`` links is included, and link cycles
    cannot loop the queue (the distance map is the visited set).
    """
def related_within(store: Any, mid: Any, hops: Any = 2) -> object {
    adj: dict = {};
    for (frm, to, kind, strength) in store["links"] {
        if ((frm in store["memories"]) and (to in store["memories"])) {
            adj.setdefault(frm, []).append(to);
            adj.setdefault(to, []).append(frm);
        }
    }
    if (mid not in store["memories"]) {
        raise KeyError(mid);
    }
    dist: dict = {mid: 0};
    queue = deque([mid]);
    while queue {
        cur = queue.popleft();
        if (dist[cur] >= hops) {
            continue;
        }
        if (cur not in adj) {
            continue;
        }
        for nbr in `list(adj[cur]) {
            if (nbr not in dist) {
                dist[nbr] = dist[cur] + 1;
                queue.append(nbr);
            }
        }
    }
    return sorted(
        x
        for x in dist
        if (x != mid)
    );
}

"""Canonical contradictory pairs ``[[a, b], ...]`` with a < b, sorted.

    One entry per distinct ``contradicts`` link, direction ignored.
    """
def contradiction_pairs(store: Any) -> object {
    pairs: set = set();
    for (frm, to, kind, strength) in store["links"] {
        if (kind != "contradicts") {
            continue;
        }
        if ((frm not in store["memories"]) or (to not in store["memories"])) {
            continue;
        }
        pairs.add((frm, to) if (frm < to) else (to, frm));
    }
    return sorted([a, b] for (a, b) in pairs);
}

candidate_osp_jac:
"""Reify construct-level dependencies into resource-level depends_on, lifted to OSP.

Constructs become Construct nodes; the children map becomes typed
Composition edges (parent -> child); construct-level addDependency
declarations become typed Depends edges. The manual stack sweep over the
children map becomes a walker descending Composition edges whose dead ends
ARE the leaf resources; crossing a Depends edge into the target subtree is
a fresh spawn of the same leaf walker at the target construct, so every
declaration cross-products its two leaf sets. Self pairs are skipped so a
dependency on an ancestor never makes a resource depend on itself. The
claim map is the cycle policy for diamond-shaped child lists; unknown
construct paths raise KeyError exactly like the source.
Ref: open-constructs/cdk-terrain#354
"""
node Construct {
    has path: str;
}
edge Composition {}
edge Depends {}

"""Loader handle: construct paths resolve through this lookup map."""
obj Model {
    has constructs: dict[str, Construct];

    def resolve(path: str) -> Construct | None {
        return self.constructs.get(path);
    }
}

"""Deterministic fresh-graph builder from a {path: [child paths]} tree spec."""
def load_model(tree: dict[str, list[str]], deps: list[tuple[str, str]]) -> Model {
    m = Model(constructs={});
    for path in tree.keys() {
        c = Construct(path=path);
        root ++> c;
        m.constructs[path] = c;
    }
    for path in tree.keys() {
        for kid in tree[path] {
            child = m.resolve(kid);
            if child is not None {
                m.constructs[path] +>:Composition:+> child;
            }
        }
    }
    for pair in deps {
        src = m.resolve(pair[0]);
        dst = m.resolve(pair[1]);
        if src is None {
            raise KeyError(pair[0]);
        }
        if dst is None {
            raise KeyError(pair[1]);
        }
        src +>:Depends:+> dst;
    }
    return m;
}

"""Leaf collector: descends Composition edges; a dead end IS a leaf resource."""
walker LeavesWalk {
    has claimed: dict[str, bool] = {};
    has leaves: list[str] = [];

    can step with Construct entry {
        # Cycle policy: one visit per construct regardless of path count.
        if here.path in self.claimed {
            skip;
        }
        self.claimed[here.path] = True;
        # a dead end IS a leaf resource; keep walking remaining branches
        visit [->:Composition:->] else { self.leaves.append(here.path); }
    }
}

"""Every leaf resource path beneath construct ``path``, sorted."""
def leaves_under(tree: dict[str, list[str]], path: str) -> list {
    m = load_model(tree, []);
    c = m.resolve(path);
    if c is None {
        raise KeyError(path);
    }
    w = c spawn LeavesWalk(claimed={}, leaves=[]);
    return sorted(w.leaves);
}

"""Reify construct-level dependencies into leaf-to-leaf depends_on."""
def synth_dependencies(tree: dict[str, list[str]], deps: list[tuple[str, str]]) -> dict {
    m = load_model(tree, deps);
    out: dict = {};
    # one subtree walk per declaration; crossing its Depends edges spawns
    # the leaf walker inside each target subtree (the N x M cross product)
    for pair in deps {
        src = m.resolve(pair[0]);
        if src is None {
            raise KeyError(pair[0]);
        }
        sw = src spawn LeavesWalk(claimed={}, leaves=[]);
        targets: list[Construct] = [src ->:Depends:->];
        for tgt in targets {
            tw = tgt spawn LeavesWalk(claimed={}, leaves=[]);
            for s_leaf in sw.leaves {
                for d_leaf in tw.leaves {
                    if s_leaf != d_leaf {
                        if s_leaf not in out {
                            out[s_leaf] = [];
                        }
                        if d_leaf not in out[s_leaf] {
                            out[s_leaf].append(d_leaf);
                        }
                    }
                }
            }
        }
    }
    for k in out.keys() {
        out[k] = sorted(out[k]);
    }
    return out;
}

"""Dependency graph and impact analysis foundation, lifted to OSP.

Files, components, tasks, and tests become node archetypes; ownership,
dependence, and coverage become typed PartOf / DependsOn / Covers edges.
The chained reverse sweeps over dict-of-lists become a single walker over
typed edges: from each changed file it follows PartOf forward to the
owning components, then reverse DependsOn to every task depending on them,
then reverse Covers to the covering tests. The per-archetype claim map is
the cycle policy for diamonds (a task depending on two impacted components
is reached twice and reported once). A changed file owned by no component
dead-ends immediately, exactly like the source sweep.
Ref: thomascarter613/monad-workspace#165
"""
node File {
    has name: str;
}
node Component {
    has name: str;
}
node Task {
    has name: str;
}
node TestNode {
    has name: str;
}
edge PartOf {}
edge DependsOn {}
edge Covers {}

"""Loader handle: entity names resolve through these lookup maps."""
obj Model {
    has files: dict[str, File];
    has comps: dict[str, Component];
    has tasks: dict[str, Task];
    has tests: dict[str, TestNode];

    def resolve_file(name: str) -> File | None {
        return self.files.get(name);
    }
}

"""Deterministic fresh-graph builder from the {kind: {name: [rels]}} model."""
def load_model(model: dict) -> Model {
    m = Model(files={}, comps={}, tasks={}, tests={});
    comps_map: dict[str, list[str]] = model.get("components", {});
    tasks_map: dict[str, list[str]] = model.get("tasks", {});
    tests_map: dict[str, list[str]] = model.get("tests", {});
    for comp in comps_map.keys() {
        c = Component(name=comp);
        root ++> c;
        m.comps[comp] = c;
    }
    for comp in comps_map.keys() {
        owner = m.comps[comp];
        for fname in comps_map[comp] {
            f = m.resolve_file(fname);
            if f is None {
                f = File(name=fname);
                root ++> f;
                m.files[fname] = f;
            }
            f +>:PartOf:+> owner;
        }
    }
    for task in tasks_map.keys() {
        t = Task(name=task);
        root ++> t;
        m.tasks[task] = t;
        for dep in tasks_map[task] {
            dc = m.comps.get(dep);
            if dc is not None {
                t +>:DependsOn:+> dc;
            }
        }
    }
    for tst in tests_map.keys() {
        e = TestNode(name=tst);
        root ++> e;
        m.tests[tst] = e;
        for covered in tests_map[tst] {
            tk = m.tasks.get(covered);
            if tk is not None {
                e +>:Covers:+> tk;
            }
        }
    }
    return m;
}

"""Ripple walker: file -> components -> depending tasks -> covering tests."""
walker ImpactWalk {
    has claimed: dict[str, bool] = {};
    has comps: list[str] = [];
    has tasks: list[str] = [];
    has tests: list[str] = [];

    can on_file with File entry {
        # Cycle policy: one visit per file regardless of path count.
        if "f:" + here.name in self.claimed {
            skip;
        }
        self.claimed["f:" + here.name] = True;
        visit [->:PartOf:->];
    }

    can on_component with Component entry {
        if "c:" + here.name in self.claimed {
            skip;
        }
        self.claimed["c:" + here.name] = True;
        if here.name not in self.comps {
            self.comps.append(here.name);
        }
        visit [<-:DependsOn:<-];
    }

    can on_task with Task entry {
        if "t:" + here.name in self.claimed {
            skip;
        }
        self.claimed["t:" + here.name] = True;
        if here.name not in self.tasks {
            self.tasks.append(here.name);
        }
        visit [<-:Covers:<-];
    }

    can on_test with TestNode entry {
        if "e:" + here.name in self.claimed {
            skip;
        }
        self.claimed["e:" + here.name] = True;
        if here.name not in self.tests {
            self.tests.append(here.name);
        }
    }
}

"""Changed-file impact analysis: impacted components, tasks, and tests."""
def impacted(model: dict, changed_files: list) -> dict {
    m = load_model(model);
    comps: list[str] = [];
    tasks: list[str] = [];
    tests: list[str] = [];
    for fname in changed_files {
        f = m.resolve_file(fname);
        if f is None {
            continue;  # owned by no component: no impact, like the source
        }
        w = f spawn ImpactWalk(claimed={}, comps=[], tasks=[], tests=[]);
        for c in w.comps {
            if c not in comps {
                comps.append(c);
            }
        }
        for t in w.tasks {
            if t not in tasks {
                tasks.append(t);
            }
        }
        for e in w.tests {
            if e not in tests {
                tests.append(e);
            }
        }
    }
    return {"components": sorted(comps), "tasks": sorted(tasks), "tests": sorted(tests)};
}

"""Recommended verification for a change: tests covering impacted tasks."""
def recommend_tests(model: dict, changed_files: list) -> list {
    return impacted(model, changed_files)["tests"];
}

"""Incremental index updates for a document section tree, lifted to OSP.

Sections become Section nodes; the children lists and parent pointers
become typed Contains edges (parent -> child). The recursive descent over
children lists becomes a downward Rebuild walker cascading through
Contains edges -- its claim map IS the once-only guard for shared
subtrees; the link-by-link parent-pointer walk becomes an upward
Resummarize walker over reverse Contains edges that skips the changed
section it starts from. Hash-based change detection stays dict comparison:
it is domain logic, not traversal. A section that is itself rebuilt is
not resummarized; unknown section ids are skipped.
Ref: VectifyAI/PageIndex#316
"""
node Section {
    has sid: str;
}
edge Contains {}

"""Loader handle: section ids resolve through this lookup map."""
obj Doc {
    has sections: dict[str, Section];

    def resolve(sid: str) -> Section | None {
        return self.sections.get(sid);
    }
}

"""Deterministic fresh-graph builder from a {sid: {parent, children}} spec."""
def load_doc(tree: dict) -> Doc {
    d = Doc(sections={});
    for sid in tree.keys() {
        s = Section(sid=sid);
        root ++> s;
        d.sections[sid] = s;
    }
    for sid in tree.keys() {
        entry: dict = tree[sid];
        kids: list = entry.get("children", []);
        parent = d.resolve(sid);
        for kid in kids {
            k = d.resolve(kid);
            if k is not None and parent is not None {
                parent +>:Contains:+> k;
            }
        }
    }
    return d;
}

"""Downward cascade: everything beneath a changed section rebuilds."""
walker RebuildWalk {
    has claimed: dict[str, bool] = {};
    has rebuilt: list[str] = [];

    can step with Section entry {
        # Cycle policy / shared-subtree guard: rebuild each section once.
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        self.rebuilt.append(here.sid);
        visit [->:Contains:->];
    }
}

"""Upward chain: summaries recompute along impacted ancestor paths only."""
walker ResummarizeWalk {
    has claimed: dict[str, bool] = {};
    has anc: list[str] = [];
    has at_start: bool = True;

    can step with Section entry {
        if here.sid in self.claimed {
            skip;
        }
        self.claimed[here.sid] = True;
        if self.at_start {
            # the changed section itself is rebuilt, not resummarized
            self.at_start = False;
        } else {
            if here.sid not in self.anc {
                self.anc.append(here.sid);
            }
        }
        visit [<-:Contains:<-];
    }
}

"""Rebuild only affected subtrees and impacted ancestor paths."""
def reindex(tree: dict, changed: list) -> dict {
    d = load_doc(tree);
    rebuilt: list[str] = [];
    resummarized: list[str] = [];
    for sid in changed {
        s = d.resolve(sid);
        if s is None {
            continue;  # unknown section: nothing to reindex
        }
        w = s spawn RebuildWalk(claimed={}, rebuilt=[]);
        for r in w.rebuilt {
            if r not in rebuilt {
                rebuilt.append(r);
            }
        }
        u = s spawn ResummarizeWalk(claimed={}, anc=[], at_start=True);
        for a in u.anc {
            if a not in resummarized {
                resummarized.append(a);
            }
        }
    }
    # a rebuilt section is not resummarized
    kept: list[str] = [];
    for a in resummarized {
        if a not in rebuilt {
            kept.append(a);
        }
    }
    return {"rebuilt": sorted(rebuilt), "resummarized": sorted(kept)};
}

"""Section ids whose content hash differs between two document versions."""
def diff_versions(old: dict, new: dict) -> list {
    out: list[str] = [];
    for sid in old.keys() {
        if sid not in new {
            out.append(sid);
        } else {
            if old[sid]["hash"] != new[sid]["hash"] {
                out.append(sid);
            }
        }
    }
    for sid in new.keys() {
        if sid not in old {
            out.append(sid);
        }
    }
    return sorted(out);
}

source_code:
"""Span tree queries with pruned ancestor/descent walks.

Before-code synthesized from pydantic/pydantic-ai#7484: SpanNode keeps a
``parent`` back-reference plus a ``children`` list; ``ancestors()`` and
``descendants()`` are plain recursive walks. Queries evaluate
all_/no_/some_ ancestor/descendant conditions against PRUNED walks: a
``stop_recursing_when`` condition truncates the walk at matching nodes
(excluded, not descended past). The historical defect was that the pruned
walks were cached generators consumed by three separate conditions, so
only the first condition per side saw any nodes; the contract here is the
fixed semantics -- every condition evaluates against a freshly
materialized pruned list. Attribute conditions match ``attrs`` entries.
"""

STOP = "stop_recursing_when"


class SpanNode:
    def __init__(self, name, span_id, attrs=None):
        self.name = name
        self.span_id = span_id
        self.attrs = attrs or {}
        self.parent = None
        self.children = []

    def add_child(self, child):
        child.parent = self
        self.children.append(child)
        return child

    def ancestors(self):
        """Nearest-first list of ancestor nodes."""
        out = []
        cur = self.parent
        while cur is not None:
            out.append(cur)
            cur = cur.parent
        return out

    def descendants(self):
        """Pre-order list over children (duplicates kept for shared nodes)."""
        out = []

        def walk(node):
            for c in node.children:
                out.append(c)
                walk(c)

        walk(self)
        return out

    def _matches_cond(self, cond):
        return all(self.attrs.get(k) == v for k, v in cond.items())

    def _pruned_ancestors(self, stop):
        out = []
        cur = self.parent
        while cur is not None:
            if stop and cur._matches_cond(stop):
                break
            out.append(cur)
            cur = cur.parent
        return out

    def _pruned_descendants(self, stop):
        out = []

        def walk(node):
            for c in node.children:
                if stop and c._matches_cond(stop):
                    continue
                out.append(c)
                walk(c)

        walk(self)
        return out

    def matches(self, query):
        stop = query.get(STOP)
        anc = self._pruned_ancestors(stop)
        desc = self._pruned_descendants(stop)
        for cond in query.get("all_ancestors_have", []):
            if not all(a._matches_cond(cond) for a in anc):
                return False
        for cond in query.get("no_ancestor_has", []):
            if any(a._matches_cond(cond) for a in anc):
                return False
        for cond in query.get("some_ancestor_has", []):
            if not any(a._matches_cond(cond) for a in anc):
                return False
        for cond in query.get("all_descendants_have", []):
            if not all(d._matches_cond(cond) for d in desc):
                return False
        for cond in query.get("no_descendant_has", []):
            if any(d._matches_cond(cond) for d in desc):
                return False
        for cond in query.get("some_descendant_has", []):
            if not any(d._matches_cond(cond) for d in desc):
                return False
        return True

candidate_osp_jac:
"""Span tree queries with pruned ancestor/descent walks.

pydantic/pydantic-ai#7484 lifted to OSP: SpanNode becomes a node
archetype; the parent back-reference and children list collapse into one
typed ChildSpan edge family walked upward for ancestors and downward for
descendants. Query evaluation spawns a fresh pruned walk per side, so
every ancestor/descendant condition sees the full pruned closure -- the
cached-generator exhaustion defect cannot recur structurally. Prune
conditions are explicit domain policy inside the walkers.
"""
node SpanNode {
    has name: str;
    has span_id: int;
    has attrs: dict[str, str] = {};
}

edge ChildSpan {}

"""Constructor equivalent + root attachment."""
def make_span(name: str, span_id: int, attrs: dict[str, str] = {}) -> SpanNode {
    s = SpanNode(name=name, span_id=span_id, attrs=attrs);
    root ++> s;
    return s;
}

def add_child(parent: SpanNode, child: SpanNode) -> SpanNode {
    parent +>:ChildSpan:+> child;
    return child;
}

# Single condition check against a node's attrs; all pairs must hold.
def cond_holds(n: SpanNode, cond: dict) -> bool {
    for k in cond.keys() {
        if n.attrs.get(k) != cond[k] {
            return False;
        }
    }
    return True;
}

# Linear ascent over ChildSpan; nearest-first order is the walk order.
walker AncWalk {
    has stop: dict | None = None;
    has out: list[SpanNode] = [];
    has first: bool = True;

    can step with SpanNode entry {
        if self.first {
            self.first = False;
        } else {
            if self.stop is not None {
                if cond_holds(here, self.stop) {
                    skip;
                }
            }
            self.out.append(here);
        }
        visit [<-:ChildSpan:<-];
    }
}

# Down-walk; prune policy: a stop-matching node is excluded and not
# descended past. Shared child nodes are revisited (multiset semantics).
walker DescWalk {
    has stop: dict | None = None;
    has out: list[SpanNode] = [];
    has first: bool = True;

    can step with SpanNode entry {
        if self.first {
            self.first = False;
        } else {
            if self.stop is not None {
                if cond_holds(here, self.stop) {
                    skip;
                }
            }
            self.out.append(here);
        }
        visit [->:ChildSpan:->];
    }
}

def ancestors(n: SpanNode) -> list[SpanNode] {
    w = n spawn AncWalk();
    return w.out;
}

def descendants(n: SpanNode) -> list[SpanNode] {
    w = n spawn DescWalk();
    return w.out;
}

def _pruned_ancestors(n: SpanNode, stop: dict | None) -> list[SpanNode] {
    w = n spawn AncWalk(stop=stop);
    return w.out;
}

def _pruned_descendants(n: SpanNode, stop: dict | None) -> list[SpanNode] {
    w = n spawn DescWalk(stop=stop);
    return w.out;
}

def matches(n: SpanNode, query: dict) -> bool {
    stop: dict | None = query.get("stop_recursing_when");
    anc = _pruned_ancestors(n, stop);
    desc = _pruned_descendants(n, stop);
    anc_all: list[dict] = query.get("all_ancestors_have", []);
    for cond in anc_all {
        for a in anc {
            if not cond_holds(a, cond) {
                return False;
            }
        }
    }
    anc_none: list[dict] = query.get("no_ancestor_has", []);
    for cond in anc_none {
        for a in anc {
            if cond_holds(a, cond) {
                return False;
            }
        }
    }
    anc_some: list[dict] = query.get("some_ancestor_has", []);
    for cond in anc_some {
        found = False;
        for a in anc {
            if cond_holds(a, cond) {
                found = True;
            }
        }
        if not found {
            return False;
        }
    }
    desc_all: list[dict] = query.get("all_descendants_have", []);
    for cond in desc_all {
        for d in desc {
            if not cond_holds(d, cond) {
                return False;
            }
        }
    }
    desc_none: list[dict] = query.get("no_descendant_has", []);
    for cond in desc_none {
        for d in desc {
            if cond_holds(d, cond) {
                return False;
            }
        }
    }
    desc_some: list[dict] = query.get("some_descendant_has", []);
    for cond in desc_some {
        found = False;
        for d in desc {
            if cond_holds(d, cond) {
                found = True;
            }
        }
        if not found {
            return False;
        }
    }
    return True;
}
